PROCEDURE PP_SEQ_NRO_DOCU IS
/*Revisado el 4/12/96 por Eitel*/
BEGIN

  :BDOC.DOC_CLAVE := FIN_SEQ_DOC_NEXTVAL;

--
EXCEPTION
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR_PLSQL;
END;

PROCEDURE PP_TRAER_DESC_PROV IS
/* Revisado el 4/12/96 por Eitel */
BEGIN
    SELECT PROV_CODIGO, PROV_RAZON_SOCIAL
      INTO :BDOC.DOC_PROV, :BDOC.S_DOC_CLI_NOM
      FROM FIN_PROVEEDOR, FIN_PROV_EMPRESA
      WHERE PROV_CODIGO = PREM_PROV
        AND PREM_PROV   = :BDOC.S_CUENTA
        AND PREM_EMPR   = :PARAMETER.P_EMPRESA
        AND PREM_MON    = :BDOC.DOC_MON;
--
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    :BDOC.S_DOC_CLI_NOM := NULL;
    pl_me('Proveedor inexistente!');
  WHEN FORM_TRIGGER_FAILURE THEN
    RAISE FORM_TRIGGER_FAILURE;
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR_PLSQL;
END;

PROCEDURE PP_TRAER_DESC_CLI IS
/* Revisado el 4/12/96 por Eitel */
v_en_informconf varchar2(1);
e_en_informconf exception;
v_incojudicial  varchar2(1);
e_incojudicial  exception;
v_permitecobrar	varchar2(2) := ADRE.BUSCA_PERMISO('FINC004', user, 'PERMITE_PROCESAR_CLIENTES_JUDICIAL_INCOMBRABLES');

BEGIN
    SELECT CLI_CODIGO, CLI_NOM, CLI_IND_POTENCIAL, cli_ruc_nuevo||'-'||cli_ruc_dv, NVL(CLI_EXENTO_INTERES, 'N')
      INTO :BDOC.DOC_CLI, :BDOC.S_DOC_CLI_NOM, v_en_informconf, :BDOC.S_CUENTA_RUC, :BDOC.S_CLI_EXENTO_INTERES
      FROM ADRE.FIN_CLIENTE, ADRE.FIN_CLI_EMPRESA
      WHERE CLI_CODIGO = CLEM_CLI
        AND CLEM_EMPR  = :PARAMETER.P_EMPRESA
        AND CLEM_CLI   = :BDOC.S_CUENTA
				AND CLEM_MON   = :BDOC.DOC_MON;

	  BEGIN
	  SELECT 'S' 
	  into v_incojudicial
		FROM ADRE.FIN_CLIENTE
		WHERE CLI_EST_CLI IN ('O', 'J', 'N', 'F')
		AND v_permitecobrar = 'N'
		AND CLI_CODIGO = :BDOC.S_CUENTA;
		EXCEPTION WHEN OTHERS THEN v_incojudicial:= 'N';
	  END;

	  if nvl(v_en_informconf, 'N') = 'S' and v_permitecobrar = 'N' then
	  	raise e_en_informconf;
	  end if;

	  if v_incojudicial = 'S' then
	  	raise e_incojudicial;
	  end if;

EXCEPTION
WHEN e_incojudicial THEN 
		PL_ME('Cuenta Judicializada/Incobrable, Comunicarse al Dpto. Cobranzas.');
	WHEN e_en_informconf THEN
		PL_ME('El Cliente se encuentra en Informconf. Favor comunicarse con el departamento de Cobranzas.');
		raise FORM_TRIGGER_FAILURE;	  	
  WHEN NO_DATA_FOUND THEN
    :BDOC.S_DOC_CLI_NOM := NULL;
    pl_me('Cliente inexistente!');
  WHEN FORM_TRIGGER_FAILURE THEN
    RAISE FORM_TRIGGER_FAILURE;
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR_PLSQL;
END;

PROCEDURE PP_VERIF_EXIST_CTA_BANC IS
CURSOR CUR_CURSOR_CTA IS
	SELECT CTA_CODIGO, BCO_DESC, CTA_DESC, CTA_MON, MON_DESC, CTA_BLOQUEADA
 	 FROM ADRE.FIN_CUENTA_BANCARIA, ADRE.FIN_BANCO, ADRE.GEN_MONEDA
	 WHERE (CTA_EMPR=NVL(:PARAMETER.P_EMPRESA,1) AND CTA_CODIGO=:BDOC.DOC_CTA_BCO)
	 AND CTA_BCO = BCO_CODIGO(+)	AND CTA_MON = MON_CODIGO(+);

CURSOR CUR_CURSOR_PERMISO_CTA IS
  SELECT OPER_CODIGO
  FROM  ADRE.GEN_OPERADOR_CAJA_CONS, ADRE.GEN_OPERADOR
  WHERE (OPCC_CAJA=:BDOC.DOC_CTA_BCO AND OPER_CODIGO=OPCC_OPERADOR AND OPER_LOGIN=:PARAMETER.P_USER); 

  SALIR        EXCEPTION;
  vDATA_FOUND    BOOLEAN;  
  vMANY_ROWS     BOOLEAN;
  vCTA_BLOQUEADA BOOLEAN;
  vPERMISO_CAJA  BOOLEAN;
BEGIN
  FOR i IN CUR_CURSOR_CTA LOOP    
	   COPY( i.BCO_DESC, 'BDOC.BCO_DESC');
	   COPY( i.CTA_DESC, 'BDOC.CTA_DESC');   
	   COPY( i.CTA_MON , 'BDOC.DOC_MON' );   
	   COPY( i.MON_DESC, 'BDOC.MON_DESC');      
	  IF i.CTA_BLOQUEADA LIKE 'S%' THEN
	      vCTA_BLOQUEADA := TRUE;
	  END IF;
	  IF vDATA_FOUND THEN	   
	     vMANY_ROWS := TRUE;
	     EXIT;
	  END IF;   
	   vDATA_FOUND := TRUE;
  END LOOP;  

  IF vDATA_FOUND IS NULL THEN          
		 MESSAGE('Número de caja inexistente.', NO_ACKNOWLEDGE);		 
		 RAISE FORM_TRIGGER_FAILURE;
  END IF;
  IF vMANY_ROWS THEN     
     MESSAGE('El número de caja esta duplicado en el sistema.', NO_ACKNOWLEDGE);		 
     RAISE FORM_TRIGGER_FAILURE;
  END IF;    
  IF vCTA_BLOQUEADA THEN
     MESSAGE('La cuenta bancaria '||:BDOC.DOC_CTA_BCO||' esta bloqueada. Consulte con el Dpto. de Finanzas.', NO_ACKNOWLEDGE);
     RAISE FORM_TRIGGER_FAILURE;
  END IF;  

	IF (NVL(:BDOC.COB_TALO_MON, :BDOC.DOC_MON) <> :BDOC.DOC_MON) THEN
			PL_ME('La moneda del talonario no coincide con la de la caja.');
	END IF;
  PP_TRAER_DESC_MONE(:BDOC.DOC_MON, :BDOC.MON_DESC, :BDOC.MON_SIMBOLO, :BDOC.W_MON_DEC_IMP);  

  FOR x IN CUR_CURSOR_PERMISO_CTA LOOP    
	   vPERMISO_CAJA := TRUE;
	   EXIT;
  END LOOP;    
  IF vPERMISO_CAJA IS NULL THEN
  	MESSAGE(' Requiere de permisos especiales para operar con la caja '||:BDOC.DOC_CTA_BCO||' Presione F9 para ver opciones.', NO_ACKNOWLEDGE);
  	RAISE FORM_TRIGGER_FAILURE;
  END IF;
  PP_ESTABLECER_FORMATO;

   IF :BDOC.DOC_MON = 1 THEN
    	:BDOC.S_TASA_OFIC := 1;
    	:BDOC.S_TASA_OFIC_AUX := :BDOC.S_TASA_OFIC;
   ELSE
    	IF NVL(:BDOC.S_TASA_OFIC,1) = 1 THEN
    	   :BDOC.S_TASA_OFIC := ROUND( FP_DEVU_COTI(:BDOC.DOC_MON, :BDOC.DOC_FEC_DOC), 4);
    	   :BDOC.S_TASA_OFIC_AUX := :BDOC.S_TASA_OFIC;
    	END IF;  
   END IF;
EXCEPTION WHEN SALIR THEN NULL;  
END;

PROCEDURE PP_CARGAR_DATOS IS
CURSOR C_GEN_EMPRESA IS
SELECT EMPR_CLI_CODIGO, EMPR_PROV_CODIGO FROM ADRE.GEN_EMPRESA WHERE EMPR_CODIGO=:PARAMETER.P_EMPRESA;

vPUNTO_EXPE_USER	VARCHAR2(8);
BEGIN

IF :PARAMETER.EMPR_CLI_CODIGO IS NULL THEN
	FOR i IN 	C_GEN_EMPRESA LOOP
	:PARAMETER.EMPR_CLI_CODIGO  := i.EMPR_CLI_CODIGO;
	:PARAMETER.EMPR_PROV_CODIGO := i.EMPR_PROV_CODIGO;
	END LOOP;
END IF;

  :BENCA.S_USUARIO       := :PARAMETER.P_USER;
  :BENCA.S_FECHA         := TO_CHAR(:PARAMETER.P_SYSDATE, 'DD-MM-YYYY');

  :BENCA.S_DESC_EMPRESA  := :PARAMETER.P_DESC_EMPRESA;
  :BENCA.S_DESC_SUCURSAL := :PARAMETER.P_DESC_SUCURSAL;
  :BENCA.S_DESC_PROGRAMA := :PARAMETER.P_DESC_PROGRAMA;
  :BENCA.S_PROGRAMA      := :PARAMETER.P_PROGRAMA;
  :BPIE.SELEC_TODOS      := 'N';
  :PARAMETER.P_SELECCION :=  NULL;



  SELECT CONF_MON_US, CONF_MON_LOC
  INTO :PARAMETER.P_MON_US, :PARAMETER.P_MON_LOC
  FROM   GEN_CONFIGURACION;

  :PARAMETER.P_CANT_DECIMALES_LOC := FL_MON_DEC_IMP(:PARAMETER.P_MON_LOC);


  SELECT CONF_RECIBO_PAGO_EMIT, CONF_RECIBO_PAGO_REC,
         CONF_NOTA_CR_EMIT,     CONF_NOTA_CR_REC,
         CONF_FACT_CR_EMIT,     CONF_FACT_CR_REC,
         CONF_NOTA_DB_EMIT,     CONF_NOTA_DB_REC,
         CONF_CONCEPTO_COBRO,   CONF_CONCEPTO_PAGO,
         CONF_CONC_PAGO_NC,     CONF_TMOV_PAGO_NC,
         CONF_TMOV_DEVOL_ADEL_CLI, CONF_CONC_CADCLI,
         CONF_ADELANTO_CLI,
         CONF_TMOV_DEVOL_ADEL_PRO, CONF_CONC_CADPRO,
         CONF_ADELANTO_PRO,
         CONF_CONC_PAGO_NC_REC, CONF_TMOV_PAGO_NC_REC
  INTO   :PARAMETER.P_CONF_RECIBO_PAGO_EMIT, :PARAMETER.P_CONF_RECIBO_PAGO_REC,
         :PARAMETER.P_CONF_NOTA_CR_EMIT,     :PARAMETER.P_CONF_NOTA_CR_REC,
         :PARAMETER.P_CONF_FACT_CR_EMIT,     :PARAMETER.P_CONF_FACT_CR_REC,
         :PARAMETER.P_CONF_NOTA_DB_EMIT,     :PARAMETER.P_CONF_NOTA_DB_REC,
         :PARAMETER.P_CONF_CONCEPTO_COBRO,   :PARAMETER.P_CONF_CONCEPTO_PAGO,
         :PARAMETER.P_CONF_CONC_PAGO_NC,     :PARAMETER.P_CONF_TMOV_PAGO_NC,
         :PARAMETER.P_CONF_TMOV_DEVOL_ADEL_CLI, :PARAMETER.P_CONF_CONC_CADCLI,
         :PARAMETER.P_CONF_ADELANTO_CLI,
         :PARAMETER.P_CONF_TMOV_DEVOL_ADEL_PRO, :PARAMETER.P_CONF_CONC_CADPRO,
         :PARAMETER.P_CONF_ADELANTO_PRO,
         :PARAMETER.P_CONF_CONC_PAGO_NC_REC, :PARAMETER.P_CONF_TMOV_PAGO_NC_REC
  FROM   ADRE.FIN_CONFIGURACION
  WHERE  CONF_EMPR = :PARAMETER.P_EMPRESA;



  IF :PARAMETER.P_CONF_CONC_PAGO_NC IS NULL THEN
    pl_me('Falta configurar el concepto de pago de nota de credito emitida!');
  END IF;

  IF :PARAMETER.P_CONF_TMOV_PAGO_NC IS NULL THEN
    pl_me('Falta configurar el tipo de mov. de pago de nota de credito emitida!');
  END IF;

  IF :PARAMETER.P_CONF_CONC_PAGO_NC_REC IS NULL THEN
    pl_me('Falta configurar el concepto de pago de nota de credito recibida!');
  END IF;

  IF :PARAMETER.P_CONF_TMOV_PAGO_NC_REC IS NULL THEN
    pl_me('Falta configurar el tipo de mov. de pago de nota de credito recibida!');
  END IF;   


  :parameter.p_max_dias_cheq_faco   := to_number(fp_devu_parametro('p_max_dias_cheq_faco'));


  :parameter.p_conc_depo            := fp_devu_conc_depo_ext('deposito');    
	:parameter.p_conc_extr            := fp_devu_conc_depo_ext('extraccion');  

  :parameter.p_codi_caja_cheq_gs    := to_number(fp_devu_parametro('p_codi_caja_cheq_gs'));
  :parameter.p_codi_caja_cheq_us    := to_number(fp_devu_parametro('p_codi_caja_cheq_us'));


  :parameter.p_max_dias_cheq_faco   := to_number(fp_devu_parametro('p_max_dias_cheq_faco'));
  :parameter.p_max_dias_cheq_reci   := to_number(fp_devu_parametro('p_max_dias_cheq_reci')); 




  if :parameter.p_conc_depo is null or :parameter.p_conc_extr is null then
  	 pl_mm('debe configurar los parametros de conceptos de depositos y de extracciones');
  	 do_key('exit');
  end if;	


  if :parameter.p_codi_caja_cheq_gs is null then
  	pl_mm('falta configurar la caja para cheques gs');
  	do_key('exit');
  end if;	


  if :parameter.p_codi_caja_cheq_us is null then
  	pl_mm('falta configurar la caja para cheques us');
  	do_key('exit');
  end if;	


  if :parameter.p_max_dias_cheq_faco is null then
  	pl_mm('falta configurar la cantidad maxima de dias para cheques en fact. contado');
  	do_key('exit');
  end if;	


  :BDOC.DOC_TIPO_MOV := 6;

  PP_TRAER_DESC_TMOV;

  :BDOC.DOC_CLI       := NULL;
  :BDOC.DOC_PROV      := NULL;
  :BDOC.S_DOC_CLI_NOM := NULL;
  :BDOC.S_CUENTA      := NULL;

	BEGIN
		TOOL_ENV.GETVAR('AUTOIMPRESION', :PARAMETER.P_AUTOIMPRESION);
	EXCEPTION
		WHEN OTHERS THEN 
		:PARAMETER.P_AUTOIMPRESION := 'N';
	END;




	begin
		select oper_punto_expe into vPUNTO_EXPE_USER from adre.gen_operador where oper_login = :PARAMETER.P_USER;
	exception when others then vPUNTO_EXPE_USER := null;
	end;	

	if vPUNTO_EXPE_USER is not null then 
		:BDOC.PUNTO_EXPE := vPUNTO_EXPE_USER;
	else
		TOOL_ENV.GETVAR('PUNTO_EXPE', :BDOC.PUNTO_EXPE);
	end if;

	 TOOL_ENV.GETVAR('PUNTO_EXPE', :BDOC.PUNTO_EXPE);
   IF :BDOC.PUNTO_EXPE IS NULL THEN
     PL_MM('Debe configurar el Punto de Expedición'); 
     DO_KEY('EXIT');
   END IF;   

  :BDOC.DOC_SUC_PUNTO_EXP  := TO_NUMBER(SUBSTR(RTRIM(LTRIM(:BDOC.PUNTO_EXPE)), 1,3));
  :BDOC.DOC_PUNTO_EXP      := TO_NUMBER(SUBSTR(RTRIM(LTRIM(:BDOC.PUNTO_EXPE)), 5,3));


  PL_FORMAT_MASK('BCLIPROV.SALDO_GS'	, 0);
  PL_FORMAT_MASK('BCLIPROV.SALDO_USD'	, 2);

  SET_ITEM_PROPERTY('BCLIPROV.TITULO', VISIBLE, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BCLIPROV.CODIGO', VISIBLE, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BCLIPROV.SALDO_GS', VISIBLE, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BCLIPROV.SALDO_USD', VISIBLE, PROPERTY_FALSE);


END;

PROCEDURE PP_EJECUTAR_CONSULTA_CUO IS
CURSOR CLI_CUR IS    
      SELECT DOC_NRO_DOC, DOC_FEC_DOC, CUO_FEC_VTO, DOC_OBS, CUO_IMP_MON, CUO_SALDO_MON, CUO_CLAVE_DOC, DOC_CLI,       
      DECODE(:BDOC.S_CLI_EXENTO_INTERES, 'S', 0, ADRE.FA_CALC_INTERESES_A_UNA_FECHA(CUO_CLAVE_DOC, CUO_FEC_VTO, :BDOC.DOC_FEC_DOC)) AS INTERES, DOC_CUO_CLAVE
      FROM ADRE.FIN_DOCUMENTO , ADRE.FIN_CUOTA
      WHERE CUO_CLAVE_DOC = DOC_CLAVE
      AND DOC_MON  = :BDOC.DOC_MON
      AND DOC_EMPR = :PARAMETER.P_EMPRESA
      AND ((DOC_CLI = :BDOC.S_CUENTA AND :BDOC.DOC_TIPO_MOV = :PARAMETER.p_CONF_RECIBO_PAGO_EMIT AND DOC_TIPO_MOV IN (:PARAMETER.P_CONF_FACT_CR_EMIT, :PARAMETER.P_CONF_NOTA_DB_EMIT)))
      AND CUO_SALDO_MON > 0
      ORDER BY NVL(DOC_CUO_VTO, CUO_FEC_VTO), DOC_FEC_DOC, DOC_NRO_DOC;

CURSOR C_INTERES_PAGADO(P_DOC_CUO_CLAVE IN NUMBER, P_DOC_CUO_VTO IN DATE) IS	 
	 SELECT DOC_CUO_CLAVE, SUM(DOC_SALDO_MON) AS DOC_INTERES_SALDO
      FROM ADRE.FIN_DOCUMENTO WHERE  DOC_CUO_CLAVE=P_DOC_CUO_CLAVE AND DOC_CUO_VTO=P_DOC_CUO_VTO GROUP BY DOC_CUO_CLAVE;

DOC_INTERES_SALDO   Number(10);
vCADENA_CHAR      VARCHAR2(21);

BEGIN

  GO_BLOCK('BCUO');  
  CLEAR_BLOCK(NO_VALIDATE);  
  FIRST_RECORD;

    FOR RCUO IN CLI_CUR LOOP
    	vCADENA_CHAR  	  := 0 ;
    	DOC_INTERES_SALDO := 0 ;
     :bcuo.s_contador   := 0 ;

    --> Agregado por Heber para restar el interes moratorio cobrado.    
    IF :BDOC.S_CLI_EXENTO_INTERES = 'N' THEN    	
    	FOR i IN C_INTERES_PAGADO(RCUO.CUO_CLAVE_DOC, RCUO.CUO_FEC_VTO) LOOP
    	   DOC_INTERES_SALDO := NVL(i.DOC_INTERES_SALDO,0);
    	END LOOP;
    END IF; 	

    :BCUO.CUO_NRO_DOC     := RCUO.DOC_NRO_DOC; SYNCHRONIZE;
    :BCUO.DOC_FEC_DOC     := RCUO.DOC_FEC_DOC;
    :BCUO.CUO_FEC_VTO     := RCUO.CUO_FEC_VTO;
    :BCUO.CUO_DOC_OBS     := RCUO.DOC_OBS;
    :BCUO.CUO_IMP_MON     := RCUO.CUO_IMP_MON;
    :BCUO.CUO_SALDO_MON   := RCUO.CUO_SALDO_MON;
    :BCUO.CUO_CLAVE_DOC   := RCUO.CUO_CLAVE_DOC;
    :BCUO.CLI_CODIGO      := RCUO.DOC_CLI;
    :BCUO.S_IMP_INTERES   := ( RCUO.INTERES - DOC_INTERES_SALDO );
    :BCUO.S_DOC_CUO_CLAVE := RCUO.DOC_CUO_CLAVE ;
    :BCUO.DA              := ROUND(:PARAMETER.P_SYSDATE - RCUO.CUO_FEC_VTO );
    vCADENA_CHAR          := '%'||RCUO.CUO_CLAVE_DOC||',%';

      IF :BCUO.S_DOC_CUO_CLAVE IS NOT NULL THEN      	        
        SET_ITEM_INSTANCE_PROPERTY('BCUO.CUO_NRO_DOC'   ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.DOC_FEC_DOC'   ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.DA'            ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.CUO_FEC_VTO'   ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.S_IMP_INTERES' ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.CUO_IMP_MON'   ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.CUO_SALDO_MON' ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
        SET_ITEM_INSTANCE_PROPERTY('BCUO.S_NVO_SALDO'   ,CURRENT_RECORD, VISUAL_ATTRIBUTE, UPPER('VISUAL_FONDO_VERDE') );
      END IF;

   IF :PARAMETER.P_SELECCION IS NOT NULL AND :BDOC.S_CUENTA <> :PARAMETER.EMPR_CLI_CODIGO THEN   
         vCADENA_CHAR :=  FP_EXTRAER_CADENA_CLAVE(:PARAMETER.P_SELECCION, RCUO.CUO_CLAVE_DOC||TO_CHAR(:BCUO.CUO_FEC_VTO,'DDMMYYYY'), ','); 
     IF vCADENA_CHAR = RCUO.CUO_CLAVE_DOC||TO_CHAR(RCUO.CUO_FEC_VTO,'DDMMYYYY') THEN
       :bcuo.s_marca := upper('x');
     END IF;
   END IF;
   IF GET_ITEM_INSTANCE_PROPERTY('BCUO.CUO_NRO_DOC' , CURRENT_RECORD, VISUAL_ATTRIBUTE) = 'VISUAL_FONDO_VERDE' 
   	   AND :BCUO.DOC_FEC_DOC = :BCUO.CUO_FEC_VTO AND :BCUO.CUO_FEC_VTO = :PARAMETER.P_SYSDATE AND :BCUO.S_MARCA IS NULL THEN
   	    :bcuo.s_marca := upper('x');
   END IF;
   NEXT_RECORD;
   END LOOP;

  FIRST_RECORD;    
  :BPIE.SELEC_TODOS := 'N';

  IF :BCUO.CUO_CLAVE_DOC IS NULL THEN
     GO_ITEM('BDOC.DOC_OBS');
     PL_ME('No existen comprobantes pendientes!');
  END IF;
EXCEPTION WHEN OTHERS THEN PL_ME('Buscar cuotas. ' || SQLERRM);


END;

PROCEDURE PP_TRAER_DESC_TMOV IS
BEGIN
 --   IF :BDOC.DOC_TIPO_MOV IN  (:PARAMETER.p_CONF_RECIBO_PAGO_EMIT,:PARAMETER.p_CONF_RECIBO_PAGO_REC,:PARAMETER.p_CONF_TMOV_PAGO_NC,:PARAMETER.p_CONF_TMOV_PAGO_NC_REC,:PARAMETER.p_CONF_TMOV_DEVOL_ADEL_CLI,:PARAMETER.p_CONF_TMOV_DEVOL_ADEL_PRO)   AND :BDOC.DOC_TIPO_MOV IS NOT NULL     THEN
       SELECT TMOV_DESC, TMOV_TIPO, TMOV_IND_ER, ETC_CLAVE_CTACO
         INTO   :BDOC.TMOV_DESC, :BDOC.DOC_TIPO_SALDO,:BDOC.W_IND_ER, :BDOC.TMOV_CTA_CONT
         FROM  GEN_TIPO_MOV, GEN_EMP_TMOV_CTACO
         WHERE TMOV_CODIGO = ETC_TIPO_MOV(+)
           AND ETC_EMPR(+) = :PARAMETER.P_EMPRESA
           AND TMOV_CODIGO = :BDOC.DOC_TIPO_MOV;

       IF :BDOC.TMOV_CTA_CONT IS NULL THEN
          pl_me('Falta definir CUENTA CONTABLE'
                           ||' para este tipo de movimiento con GENM026!');
       END IF;
   /*
    ELSE
       :BDOC.TMOV_DESC      := NULL;
       :BDOC.DOC_TIPO_SALDO := NULL;
       :BDOC.W_IND_ER       := NULL;
       pl_me('Opción no válida - Ingrese '||
		TO_CHAR(:PARAMETER.P_CONF_RECIBO_PAGO_EMIT)||', '||
		TO_CHAR(:PARAMETER.P_CONF_RECIBO_PAGO_REC)||', '||
                TO_CHAR(:PARAMETER.P_CONF_TMOV_PAGO_NC)||', '||
                TO_CHAR(:PARAMETER.P_CONF_TMOV_DEVOL_ADEL_CLI)||', '||
                TO_CHAR(:PARAMETER.P_CONF_TMOV_DEVOL_ADEL_PRO)||', '||
                TO_CHAR(:PARAMETER.P_CONF_TMOV_PAGO_NC_REC)||'!');
    END IF;
    */
--
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    :BDOC.TMOV_DESC      := NULL;
    :BDOC.TMOV_CTA_CONT  := NULL;
    :BDOC.DOC_TIPO_SALDO := NULL;
    :BDOC.W_IND_ER       := NULL;
    pl_me('Tipo de movimiento inexistente!');
  WHEN FORM_TRIGGER_FAILURE THEN
    RAISE FORM_TRIGGER_FAILURE;
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR_PLSQL;
END;

procedure pp_validar_totales is
  tot_pago number := 0;
  contador number := 0;
begin
-- verifica que se haya asignado una cuota para pagar,
-- que la suma de los importes de los pagos de las cuota sea = al
-- total del pago o recibo, y, actualiza los saldos.

  go_item('bcuo.s_marca');
  first_record;

  if :BDOC.DOC_CLI  <> :BCUO.CLI_CODIGO then
  	 pl_me('El cliente no corresponde a las cuotas a cancelar....');
  end if;	

  loop
    if upper(:bcuo.s_marca) like upper('x') then
    	if nvl(:bdoc.doc_mon,1) = 1 then
          tot_pago := tot_pago + nvl(:bcuo.s_imp_pago,0);
    	else
    	  	--tot_pago := round(tot_pago,2) + round(nvl(:bcuo.s_imp_pago,0),2);
    	  	tot_pago := tot_pago + nvl(:bcuo.s_imp_pago,0);
    	end if;
    	contador := nvl(contador, 0) + 1;
    end if;
    exit when  :system.last_record = upper('true') ;
    next_record;
  end loop;


  --
  if tot_pago = 0 then
     first_record;
     pl_me('el pago debe asignarse por lo menos a un documento!');
  end if;

  if contador > 40 and nvl(:parameter.p_autoimpresion, 'N') = 'S' then
  	pl_me('Solo puede cargar hasta 40 registros.');
  end if;
  --


IF :BDOC.DOC_MON = 1 THEN   

  IF tot_pago <> nvl(:bdoc.doc_neto_exen_mon,0) THEN	  	
  	IF (tot_pago - :bdoc.doc_neto_exen_mon) NOT BETWEEN -1 AND 1 THEN -- Linea agregada para los casos de diferencia por redondeo. By Heber 23/02/2017
     go_item('bdoc.doc_neto_exen_mon');
     pl_me('existen diferencias entre el importe del pago y los importes de los documentos asignados!'||chr(13)||'TOTAL PAGO='||tot_pago||' DOC. ASIGNADOS='||nvl(:bdoc.doc_neto_exen_mon,0));
    END IF;
  END IF;  

ELSE  	

  	IF (tot_pago - :bdoc.doc_neto_exen_mon) NOT BETWEEN -0.5 AND 0.5 THEN -- Linea agregada para los casos de diferencia por redondeo. By Heber 23/02/2017
     go_item('bdoc.doc_neto_exen_mon');
     pl_me('existen diferencias entre el importe del pago y los importes de los documentos asignados!'||chr(13)||'TOTAL PAGO='||tot_pago||' DOC. ASIGNADOS='||nvl(:bdoc.doc_neto_exen_mon,0));
  	END IF;

END IF;

--
exception
  when form_trigger_failure then
    raise form_trigger_failure;
  when others then
    pl_exhibir_error_plsql;
end;

