procedure pp_actualizar_registro is
  salir exception;  
  v_indi_mone varchar2(1);
  begin

  if :bdoc.s_doc_fec_oper is null then
    raise salir;
  end if;
  IF TO_NUMBER(TO_CHAR(:BDOC.DOC_FEC_OPER, 'YYYYMM')) <> TO_NUMBER(TO_CHAR(:BDOC.DOC_FEC_DOC, 'YYYYMM')) THEN
  	PL_ME('El mes de la fecha de operación debe ser igual a la fecha del comprobante');
  END IF;
  IF :BDOC.DOC_FEC_OPER < :BDOC.DOC_FEC_DOC THEN
  	PL_ME('La fecha de operación no puede ser inferior a la fecha del documento');
  END IF;  

  PP_VALIDAR_CIERRE_CAJA ;  

  if ( :bdoc.cob_talo_modalidad in ('Autoimpreso')) then
		PP_VALIDAR_TALONARIO;
  end if;

  if :bcuo.sum_contador_seleccion > 24 then
    PL_EXHIBIR_ERROR('La dimensión del recibo acepta hasta un máximo de 24 pagos.');
  end if;

 	pp_validar_totales;  
	pp_validar_importes;  
  pp_validar_cheq_cuot;
  pp_validar_bloque_bmp ; --> Validar bloque Medios de pago.

  pp_actualizar_documento_fin; 

  if :bdoc.form_pago = 2 then
 	 pp_actualizar_cheques;
  end if;  

  commit_form;
  if not form_success then
     --clear_form(no_validate);
     --pp_cargar_datos;
     PL_ME('Registro no actualizado.');
     raise salir;
  else  	 
  	 	--if ( lower(:bdoc.cob_talo_modalidad) like 'autoimpreso%' and :bdoc.s_cuenta <> :PARAMETER.EMPR_CLI_CODIGO ) then
  	 	if ( lower(:bdoc.cob_talo_modalidad) like 'autoimpreso%' ) then
  	 	 pp_imprimir_recibo;
  	 	end if;
  	 begin
  	 	ADRE.PA_CANC_VALE_RECAUTOIMP_PLAN0(:BDOC.DOC_CLAVE);
  	 exception when others then pl_mm('Error. ' || sqlerrm || ' ' || dbms_error_text);  	 	
  	 end;
  	 adre.pa_update_num_fin_talo(:parameter.p_sucursal, 2, :bdoc.doc_suc_punto_exp, :bdoc.doc_punto_exp, :bdoc.cob_talo_mon, :bdoc.doc_legajo, :bdoc.cob_talo_modalidad, :bdoc.cob_talo, :bdoc.doc_nro_doc);
  	 commit_form;

  	 go_block('bmp');
  	 first_record;
  	 loop
  	 	if :bmp.mp_clave_transferencia is not null then
  	 		pp_cancelar_transferencia('FINI002', 'CANCELAR TRANSFERENCIAS BANCARIAS');
  	 		EXIT;
  	 	end if;
  	 	exit when :system.last_record = 'TRUE';
  	 	next_record;
  	 end loop;

     clear_form(no_validate);
     pp_cargar_datos;
     message('registro actualizado!');
  end if;
  if form_failure then
     raise form_trigger_failure;
  end if;

exception
  when salir then
     null;
end;

procedure pp_traer_concepto  (p_codi in number, p_clave_ctaco out number, p_tipo_saldo out varchar2) is
begin

    select fcon_clave_ctaco, fcon_tipo_saldo
    into p_clave_ctaco, p_tipo_saldo
    from fin_concepto
    where fcon_clave = p_codi;

exception
  when no_data_found then
    pl_me('Concepto inexistente!');


end;

PROCEDURE PP_TRAER_DESC_VEND IS
BEGIN
    SELECT EMPL_NOMBRE
    INTO   :BDOC.DOC_LEGAJO_DESC
    FROM   PER_EMPLEADO
    WHERE  EMPL_LEGAJO = :BDOC.DOC_LEGAJO;
--
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    :BDOC.DOC_LEGAJO_DESC := NULL;
    pl_me('Empleado inexistente!');
  WHEN FORM_TRIGGER_FAILURE THEN
    RAISE FORM_TRIGGER_FAILURE;
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR_PLSQL; 
END;

