                    v_dcon_clave_ctaco,
                    v_dcon_tipo_saldo);

  v_dcon_exen_loc            := :bdoc.doc_neto_Exen_loc;
  v_dcon_exen_mon            := :bdoc.doc_neto_Exen_mon;
  v_dcon_grav_loc            := 0;
  v_dcon_grav_mon            := 0;
  v_dcon_iva_loc             := 0;
  v_dcon_iva_mon             := 0;
  v_dcon_clave_imp           := null;
  v_dcon_ind_tipo_iva_compra := null;
  v_dcon_mon                 := v_mon;
  v_dcon_tasa_me             := v_tasa_me;
  v_dcon_tasa_mon            := null;

  pp_insert_fin_doc_concepto(v_dcon_clave_doc,
                             v_dcon_item,
                             v_dcon_clave_concepto,
                             v_dcon_clave_ctaco,
                             v_dcon_tipo_saldo,
                             v_dcon_exen_loc,
                             v_dcon_exen_mon,
                             v_dcon_grav_loc,
                             v_dcon_grav_mon,
                             v_dcon_iva_loc,
                             v_dcon_iva_mon,
                             v_dcon_clave_imp,
                             v_dcon_ind_tipo_iva_compra,
                             v_dcon_mon,
                             v_dcon_tasa_me,
                             v_dcon_tasa_mon);

  --insertar los pagos...

  go_block('bcuo');
  first_record;
  loop
    if upper(:bcuo.s_marca) like upper('x') then
      :bcuo.s_imp_pago_loc := round(nvl(:bcuo.s_imp_pago, 0) *
                                    :bdoc.s_tasa_ofic,
                                    :parameter.p_cant_decimales_loc);
      v_tot_imp_pago_loc   := v_tot_imp_pago_loc + :bcuo.s_imp_pago_loc;

    end if;
    exit when :system.last_record = upper('true');
    next_record;
  end loop;

  --calcular la diferencia entre encabezado loc y detalles loc
  v_diferencia := nvl(:bdoc.doc_neto_exen_loc, 0) - v_tot_imp_pago_loc;
  --asignar la diferencia al primer registro marcado
  first_record;
  loop
    if upper(:bcuo.s_marca) = upper('x') then
      :bcuo.s_imp_pago_loc := :bcuo.s_imp_pago_loc + v_diferencia;

      exit;
    end if;
    exit when :system.last_record = upper('true');
    next_record;
  end loop;

  v_pag_clave_pago := :bdoc.doc_clave;
  v_pag_login      := :benca.s_usuario;
  v_pag_fec_grab   := sysdate;
  v_pag_sist       := :bdoc.doc_sist;

  first_record;
  loop
    if upper(:bcuo.s_marca) = upper('x') then

      v_pag_clave_doc := :bcuo.cuo_clave_doc;
      v_pag_fec_vto   := :bcuo.cuo_fec_vto;
      v_pag_fec_pago  := :bdoc.doc_fec_doc;
      v_pag_imp_loc   := :bcuo.s_imp_pago_loc;
      v_pag_imp_mon   := :bcuo.s_imp_pago;

      insert into fin_pago
        (pag_clave_doc,
         pag_fec_vto,
         pag_clave_pago,
         pag_fec_pago,
         pag_imp_loc,
         pag_imp_mon,
         pag_login,
         pag_fec_grab,
         pag_sist)
      values
        (v_pag_clave_doc,
         v_pag_fec_vto,
         v_pag_clave_pago,
         v_pag_fec_pago,
         v_pag_imp_loc,
         v_pag_imp_mon,
         v_pag_login,
         v_pag_fec_grab,
         v_pag_sist);
    end if;
    exit when :system.last_record = upper('true');
    next_record;
  end loop;


---- Recorrer Bloque de Medio de Pago

  go_block('bmp');
  first_record;
  loop

  	if :bmp.mp_medio_pago is not null and :bmp.mp_importe > 0 and v_doc_clave is not null then
  			/*
  			if :bmp.mp_clave_transferencia is not null then
  				declare
  					v_tbd_nro_canc adre.fin_transfer_bancarias_det.tbd_nro_canc%type;
  				begin

						select nvl(max(tbd_nro_canc),0)+1
						  into v_tbd_nro_canc
						  from adre.fin_transfer_bancarias_det
						 where tbd_clave = :bmp.mp_clave_transferencia
						 		 ;

						insert into adre.fin_transfer_bancarias_det
						            ( tbd_clave,
						              tbd_nro_canc,
						              tbd_doc_clave,
						              tbd_imp_mon,
						              tbd_imp_loc,
						              tbd_fecha_alta
						            ) values
						            (	:bmp.mp_clave_transferencia,
						              v_tbd_nro_canc,
						              v_doc_clave,
						              :bmp.mp_importe,
						              round(:bmp.mp_importe * :bdoc.s_tasa_ofic, 0),
						              :parameter.p_sysdate
						            );
					exception
						when no_data_found then
						pl_me('Ya se utilizó número de transferencia.');
						when others then 
						pl_me('Ocurrió un error al cancelar número de transferencia.');
					end;  				

  			end if;
  			*/

		    insert into adre.fac_transaccion_medio_pago 
		    (mp_doc_clave, 
		     mp_importe, 
		     mp_medio_pago, 
		     mp_nro_referencia, 
		     mp_banco_emisor, 
		     mp_cheque_nro, 
		     mp_fecha_cheque, 
		     mp_fecha_cheque_vto, 
		     mp_librador_cheque)		    
		    values (v_doc_clave, 
		     :bmp.mp_importe, 
		     :bmp.mp_medio_pago, 
		     :bmp.mp_nro_referencia, 
		     :bmp.mp_banco_emisor, 
		     :bmp.mp_cheque_nro, 
		     to_date(:bmp.mp_fecha_cheque,'dd-mm-yyyy' ), 
		     to_date(:bmp.mp_fecha_cheque_vto,'dd-mm-yyyy' ), 		    
		     :bmp.mp_librador_cheque);		     
    end if;    

    exit when :system.last_record = 'TRUE';
    next_record;
  end loop;


Exception

  /*when form_trigger_failure then
    pl_mm('Error en pp_actualizar_documento_fin..FTF');
    raise form_trigger_failure;*/
  when others then
    pl_mm('Error en pp_actualizar_documento_fin..WO' || TO_CHAR(SQLCODE) ||
          ' - ' || SQLERRM);
    rollback;
    pl_me('Avise al Dpto. de Informática');
    raise form_trigger_failure;
end;

procedure pp_traer_desc_banco(p_codi in varchar2, p_desc out varchar2) is        
begin           

  select bco_desc
  into   p_desc 
  from   fin_banco
  where  to_char(bco_codigo) = p_codi;


Exception
  when no_data_found then
     pl_me('Banco inexistente.');  
  when form_trigger_failure then
     raise form_trigger_failure;
  when others then
     pl_exhibir_error_plsql;
end;

procedure pp_validar_nro_cheq (p_bco in number, p_serie in varchar2, p_nro in varchar2) is
v_clave number;
begin
  select  cheq_clave
  into v_clave
  from fin_cheque
  where cheq_bco = p_bco
  and cheq_serie = p_serie
  and cheq_nro = p_nro;

   pl_me('Nro de Cheque existente!!!!!')  ;

Exception
	 when no_data_found then
	   null;
	 when too_many_rows then
	   pl_me('Nro de Cheque existente!!!!!')  ;

  end;

function fp_devu_max_dias_cheq (p_cli in number) return number is


v_clem_max_dias_cheq_reci number ;


begin

   select cli_max_dias_cheq_reci
   into v_clem_max_dias_cheq_reci
   from fin_cliente
   where cli_codigo = p_cli;


   if v_clem_max_dias_cheq_reci is null then
   	  v_clem_max_dias_cheq_reci := :parameter.p_max_dias_cheq_reci;
   end if;	  

   return v_clem_max_dias_cheq_reci;

 exception
  when no_data_found then
     return :parameter.p_max_dias_cheq_reci; 
  when others then
     return  :parameter.p_max_dias_cheq_reci;    
end;

function fp_devu_parametro (p_nomb_para in varchar2) return varchar2 is
v_para_valo varchar2(40);
begin

  select para_valo
  into  v_para_valo
  from come_para
  where ltrim(rtrim(upper(para_nomb))) = ltrim(rtrim(upper(p_nomb_para)));

 return v_para_valo;	

Exception
	  When no_data_found then
	     pl_mm('Parametro no encontrado!!!!! '||p_nomb_para);
	     return null;
	  when too_many_rows then
	     pl_mm('Parametro duplicado!!!'||p_nomb_para)   ;
	     return null;
	  WHEN FORM_TRIGGER_FAILURE THEN
     RAISE FORM_TRIGGER_FAILURE;
    WHEN OTHERS THEN
      PL_EXHIBIR_ERROR_PLSQL;    



end;

procedure pp_validar_repe_cheq is
  --validar que los vencimientos no se repitan    
  v_registro number;
  v_nro      number;
  v_serie    varchar2(2);
  v_bco      number;


  begin

  go_block('bcheq');
  last_record;
  v_registro := to_number(:system.cursor_record);
  for i in 1..v_registro - 1 loop
    go_record(i);
    v_nro    := :bcheq.cheq_nro;
    v_serie  := :bcheq.cheq_serie;
    v_bco    := :bcheq.cheq_bco;

      for j in i+1..v_registro loop
        go_record(j);
        if v_nro = :bcheq.cheq_nro and v_serie = :bcheq.cheq_serie and v_bco= :bcheq.cheq_bco then
          go_record(i);
          pl_me('Los cheques :'||
                           to_char(i)||' y '|| to_char(j)||
                      ' se repiten!!');
        end if;
      end loop;    
  end loop;
end;

procedure pp_validar_importes is
begin


if :bdoc.doc_mon = 1 then
  if nvl(:bcuo.sum_s_imp_pago,0) <> nvl(:bdoc.doc_neto_exen_mon,0) then

  	IF (:bcuo.sum_s_imp_pago - :bdoc.doc_neto_exen_mon) NOT BETWEEN -1 AND 1 THEN -- Linea agregada para los casos de diferencia por redondeo. By Heber 23/02/2017
  	  pl_me('El Total de pagos del detalle no puede ser distinto al total de la cabecera, Favor Verifique!!');
  	END IF;  

  end if;	

  else

  if nvl(:bcuo.sum_s_imp_pago,2) <> nvl(:bdoc.doc_neto_exen_mon,2) then ----Si la moneda es extranjera que evalúe con 2 decimales..
  	IF (:bcuo.sum_s_imp_pago - :bdoc.doc_neto_exen_mon) NOT BETWEEN -0.5 AND 0.5 THEN 
  	  pl_me('El Total de pagos del detalle no puede ser distinto al total de la cabecera, Favor Verifique!!');
  	END IF;
  end if;	

end if;



  if :bdoc.form_pago = 2 then  --si con cheque recibido
		  if nvl(:bdoc.doc_neto_Exen_mon,0)  < nvl(:bcheq.SUM_CHEQ_IMPORTE_MON_FACT,0) then
		  	 pl_me('El importe del /los Cheque/s no puede ser mayor al importe del Recibo');
		  end if;	
  end if;


end;

