v_dcon_clave_doc           number(14)   ;                          
v_dcon_item                number(4)    := 0;                          
v_dcon_clave_concepto      number(6)    ;                          
v_dcon_clave_ctaco         number(6)    ;                         
v_dcon_tipo_saldo          varchar2(1)  ;                          
v_dcon_exen_loc            number(14,4) ;                          
v_dcon_exen_mon            number(14,4) ;                          
v_dcon_grav_loc            number(14,4) ;                          
v_dcon_grav_mon            number(14,4) ;                          

v_dcon_iva_loc             number(14,4) ;                          
v_dcon_iva_mon             number(14,4) ;                          

v_dcon_clave_imp           number(8)    ;                         
v_dcon_ind_tipo_iva_compra number(1)    ;                         
v_dcon_mon                 number(2)    ;                         
v_dcon_tasa_me             number(10,4) ;                         
v_dcon_tasa_mon            number(10,4) ;

v_impo_mon                 number;
v_impo_loc                 number;

