v_impo_depo_mon number := 0;
v_impo_depo_loc number := 0;

v_impo_Extr_mon number := 0;
v_impo_extr_loc number := 0;


begin




  	if :bdoc.form_pago = 2 then --si es contado contra cheque.. 
  		go_block('bcheq');
  		first_record;
  		loop
  		   if nvl(:bcheq.cheq_importe,0) > 0 and :bcheq.cheq_nro is not null then  	  		   	

  		   	  if :bcheq.cheq_mon = 1 then
  		   	  	 v_caja_cheq := :parameter.p_codi_caja_cheq_gs;
  		   	  else
  		   	  	 v_caja_cheq := :parameter.p_codi_caja_cheq_us;
  		   	  end if;	 


  		   	  v_mon_depo := fp_Devu_mon_caja(v_caja_cheq);


  		   	  ---para el deposito 
  		   	  if :bcheq.cheq_mon   = 1 and v_mon_depo = 1 then --Cheq. Gs. Caja cheq Adel Gs..
  		   	  	  v_impo_depo_mon :=  :bcheq.cheq_importe;
  		   	  	  v_impo_depo_loc :=  :bcheq.cheq_importe;

  		   	  elsif :bcheq.cheq_mon = 1 and v_mon_depo = 2 then --cheq Gs . Caja de cheq Adel Us (muy poco probable)
  		   	     v_impo_depo_mon  := round((:bcheq.cheq_importe / :bdoc.W_DOC_TASA_US),2); 
  		   	     v_impo_depo_loc  := :bcheq.cheq_importe;
  		   	  elsif :bcheq.cheq_mon = 2 and v_mon_depo = 1 then --cheque en Us pero el deposito en Gs..
  		   	  	 v_impo_depo_mon := round((:bcheq.cheq_importe * :bdoc.w_doc_tasa_us),0) ;
  		   	  	 v_impo_depo_loc := v_impo_depo_mon;
  		   	  elsif :bcheq.cheq_mon = 2 and v_mon_depo = 2 then
  		   	  	 v_impo_depo_mon := :bcheq.cheq_importe ; 
  		   	  	 v_impo_depo_loc := round((v_impo_depo_mon* :bdoc.w_doc_tasa_us),0);  		   	  	
  		   	  end if;	



						--fin_documento --documento de deposito bancaria TM12 
						--para realizar el deposito en la caja de cheques adelantados........
						v_doc_clave                 := fin_seq_doc_nextval                  ; 						
						v_doc_clave_depo            := v_doc_clave                          ;						
						v_doc_bco_cheque            := null                                 ;
						v_doc_cond_vta              := null																	; 
						v_doc_empr                  := :bdoc.doc_empr                       ;
						v_doc_cta_bco               := v_caja_cheq                          ;						
						v_doc_suc                   := :bdoc.doc_suc                        ;
						v_doc_tipo_mov              := 12                                   ;--Deposito Bancario
						v_doc_dpto                  := null                                 ;
						v_doc_tipo_saldo            := 'D'                                  ;
						v_doc_mon                   := v_mon_depo                           ;--el deposito siempre en Gs porque la caja cheque diferidos está en Gs
						v_doc_prov                  := null																	;
						v_doc_cli                   := :bdoc.doc_cli                        ;
						v_doc_nro_doc               := :bdoc.doc_nro_doc                    ;
						v_doc_cli_nom               := null                                 ;
						v_doc_cli_dir               := null                                 ;
						v_doc_legajo                := :bdoc.doc_legajo                     ;
						v_doc_cli_ruc               := null                                 ;
						v_doc_nro_cheque            := null																	;
						v_doc_cli_tel               := null                                 ;
						v_doc_est_cheque            := null																	;
						v_doc_fec_dep_cheque        := null													        ;
						v_doc_nro_doc_dep           := null											            ;
						v_doc_cheque_certif         := null																	;
						v_doc_fec_oper              := :bdoc.doc_fec_oper                   ; 
						v_doc_fec_doc               := :bdoc.doc_fec_doc                    ;
						v_doc_iva_loc               := 0                                    ;
						v_doc_fec_cheque            := null                                 ;
						v_doc_iva_mon               := 0                                    ;
						v_doc_bruto_grav_loc        := 0                                    ;
