						v_dcon_tasa_me             := :bdoc.w_doc_tasa_us     ;                         
						if :bdoc.doc_mon = 1 then
						 v_dcon_tasa_mon           := 1 ;
						else
						 v_dcon_tasa_mon           := :bdoc.s_tasa_ofic;
						end if;	


						pp_insert_fin_doc_concepto(
						v_dcon_clave_doc           ,
						v_dcon_item                ,
						v_dcon_clave_concepto      ,
						v_dcon_clave_ctaco         ,
						v_dcon_tipo_saldo          ,
						v_dcon_exen_loc            ,
						v_dcon_exen_mon            ,
						v_dcon_grav_loc            ,
						v_dcon_grav_mon            ,
						v_dcon_iva_loc             ,
						v_dcon_iva_mon             ,
						v_dcon_clave_imp           ,
						v_dcon_ind_tipo_iva_compra ,
						v_dcon_mon                 ,
						v_dcon_tasa_me             ,
						v_dcon_tasa_mon            						
						);	




  		   end if;  		   
  		   exit when :system.last_record = upper('true');
  		   next_record;
  		 end loop; 



    end if;



  Exception
  when form_trigger_failure then
    raise form_trigger_failure;
  when others then
    pl_exhibir_error_plsql;
end;

function fp_busca_ctaco_caja (p_codi in number) return number is
v_ctaco number;
begin

  select cta_clave_ctaco
  into v_ctaco
  from fin_cuenta_bancaria
  where cta_empr = :parameter.p_empresa
  and cta_codigo = p_codi;

  return v_ctaco;

Exception
	 When no_data_found then
	   return null;


end;

FUNCTION FP_DEVU_COTI (P_MON IN NUMBER, P_FECH IN DATE)  RETURN NUMBER IS
CURSOR CUR_CURSOR IS
  SELECT COT_TASA FROM ADRE.STK_COTIZACION WHERE (COT_FEC=P_FECH AND COT_MON=P_MON);
  SALIR EXCEPTION;
  vDATA_FOUND BOOLEAN;  
  vMANY_ROWS  BOOLEAN;
BEGIN  
  FOR i IN CUR_CURSOR LOOP    
   vDATA_FOUND := TRUE;   
   IF vDATA_FOUND THEN
    RETURN i.COT_TASA;
    EXIT;
   END IF;
   EXIT;
  END LOOP;    
  IF vDATA_FOUND IS NULL THEN          
     MESSAGE('Primero debe ingresar la cotización del día '||to_char(P_FECH, 'dd-mm-yyyy')|| 'para la moneda '||P_MON, NO_ACKNOWLEDGE);          
     RETURN NULL;
     RAISE FORM_TRIGGER_FAILURE;
  END IF;
  IF vMANY_ROWS THEN     
     MESSAGE('Existe mas de una cotización para la fecha'||TO_CHAR(P_FECH,'DD-MM-YYYY')|| ' para la moneda '||P_MON, NO_ACKNOWLEDGE);     
     RETURN NULL;
     RAISE FORM_TRIGGER_FAILURE;
  END IF;    
EXCEPTION WHEN SALIR THEN NULL;  
END;

procedure pp_validar_cheq_cuot is

v_sald_cheq number := 0;

type tipo_fac_clave is table of number index by BINARY_INTEGER ;
type tipo_fac_venc  is table of date   index by BINARY_INTEGER;
type tipo_fac_impo  is table of number index by BINARY_INTEGER;
type tipo_fac_sald  is table of number index by BINARY_INTEGER;


t_fac_clave tipo_fac_clave;
t_fac_venc  tipo_fac_venc;
t_fac_impo  tipo_fac_impo;
t_fac_sald  tipo_fac_sald;

v_index   BINARY_INTEGER := 0;
v_puntero BINARY_INTEGER := 1;

v_max_dias number;

begin

v_max_dias := fp_devu_max_dias_cheq(:bdoc.s_cuenta);



  go_block('bcuo');
  first_Record;
  loop
  	 if :bcuo.s_marca = upper('x') and nvl(:bcuo.s_imp_pago,0) > 0 then
  	    v_index := v_index + 1;
  	    t_fac_clave(v_index) := :bcuo.cuo_clave_doc;
  	    if :bdoc.doc_fec_doc > :bcuo.cuo_fec_vto then  	    	
  	      t_fac_venc (v_index) := :bdoc.doc_fec_doc;
  	    else
  	      t_fac_venc (v_index) := :bcuo.cuo_fec_vto;
  	    end if;	

  	    t_fac_impo (v_index) := :bcuo.s_imp_pago;
  	    t_fac_sald (v_index) := :bcuo.s_imp_pago;


  	 end if;
  	 exit when :system.last_record = upper('true');
  	 next_record;
  end loop;	


  v_puntero := 1;

  go_block('bcheq');
  first_record;
  loop
  	 v_sald_cheq := :bcheq.cheq_importe_mon_fact;

  	  loop 
  	  	if (t_fac_venc(v_puntero) +v_max_dias) < :bcheq.cheq_fec_depositar then
  	    	  pl_me('La fecha de Vencimiento del cheque es superior a la fecha de vencimiento de la cuota');
  	    end if;	 

  	    if t_fac_sald(v_puntero) >= v_sald_cheq   then
  	        t_fac_sald(v_puntero) := t_fac_sald(v_puntero) - v_sald_cheq;
  	        if t_fac_sald(v_puntero) = 0 then
  	          v_puntero := v_puntero + 1;
  	        end if;  	        
  	        exit;
  	    else  --si el saldo del pago < al saldo del cheque
  	      v_sald_cheq := v_sald_cheq - t_fac_sald(v_puntero);
  	      v_puntero := v_puntero + 1;
  	    end if;     
  	    if v_puntero >= v_index then
  	    	  exit;
  	    end if;	  
  	  end loop;

  	 exit when :system.last_record = upper('true');
  	 next_record;

  end loop;	



end;

function fp_devu_conc_depo_ext (p_desc in varchar2)return number is
v_clave number;
begin

  select FCON_clave
  into v_clave
  from fin_concepto
  where RTRIM(LTRIM(UPPER(FCON_desc))) = LTRIM(RTRIM(UPPER(p_desc)));

  return v_clave;

exception 
	 When no_data_found then
	    pl_me('Concepto de '||p_desc||' no enconcrado');
	  when too_many_rows then
	     pl_me('CONCEPTO DE DEPOSITO/EXTRACCION DUPLICADO!!!')   ;
	  WHEN FORM_TRIGGER_FAILURE THEN
     RAISE FORM_TRIGGER_FAILURE;
    WHEN OTHERS THEN
      PL_EXHIBIR_ERROR_PLSQL;        

end;

function fp_devu_mon_caja (p_codi in number) return number is
v_mon number;
begin

  select cta_mon
  into v_mon
  from fin_cuenta_bancaria
  where cta_empr = 1
  and cta_codigo = p_codi;

  return v_mon;

Exception
	 When no_data_found then
	   v_mon := 1;
	   return v_mon;
	   pl_mm('Codigo de cuenta Bancaria Inexistente');

end;

PROCEDURE p_valida_nume(p_suc       in number,
                        p_doc_nume  in number,
                        p_tipo_talo in number,
                        p_indi_mone in VARCHAR2) is
  /*  -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  Validar que siga la secuencia según el punto de expedición..
  No debe permitir que se grabe un documento si el numero anterior no fue grabado aún, 
  o no fue registrado como anulado (que pertenezca al mismo talonario)
  Ejemplo: Si se  intenta grabar el numero 001-004- 0000100, 
  el numero anterior 001-004-0000099 deberá estar grabado en el sistema, 
  o deberá estar registrado como anulado.
  */ -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

  cursor c_talo is
    select talo_codi, talo_nume_desd, talo_nume_hast, talo_tipo_codi
      from fin_talo
     where nvl(talo_indi_acti, 'S') = 'S'
       and talo_sucu_codi = p_suc
       and talo_tipo_codi = p_tipo_talo
       and talo_indi_mone = p_indi_mone
     order by talo_codi;

  v_nume           number;
  v_indi_entro     VARCHAR2(1) := 'N';
  v_talo_codi      number;
  v_talo_tipo_codi number;
  v_talo_nume_desd number;
  V_talo_nume_hast number;

  vfecha					 date;

  v_count      number   := 0;
  v_count_anul number   := 0;

  v_count2      number := 0;
  v_count_anul2 number := 0;

  v_mone_codi number;

  v_indi_rango_infe VARCHAR2(1) := 'N';

begin
  if p_indi_mone = 'D' then
    v_mone_codi := 2;
  else
    v_mone_codi := 1;
  end if;

  v_nume := p_doc_nume;

  for x in c_talo loop
    if v_nume between x.talo_nume_desd and x.talo_nume_hast then
      v_indi_entro     := 'S';
      v_talo_codi      := x.talo_codi;
      v_talo_tipo_codi := x.talo_tipo_codi;
      v_talo_nume_desd := x.talo_nume_desd;
  	  V_talo_nume_hast := x.talo_nume_hast;
      if v_nume = x.talo_nume_desd then
        v_indi_rango_infe := 'S';
      end if;
      exit;
    end if;
  end loop;
  if v_indi_entro = 'N' then
    pl_me('El nro de documento no pertenece a ningun talonario activo');
  end if;

  --ahora verificar que el numero anterior este cargado en el sistema, o q esté registrado como anulado

  if v_indi_rango_infe = 'N' then
    select count(*)
      into v_count
      from fin_documento
     where doc_tipo_mov in
           (select deta_tmov_codigo
              from fin_tipo_talo, fin_tipo_talo_deta
             where deta_tipo_codi = v_talo_tipo_codi)
       and doc_suc = p_suc
       and doc_nro_doc = (v_nume - 1)
       and doc_mon = v_mone_codi
       and doc_empr = 1
       and trunc(doc_fec_doc) >= trunc(sysdate) - 900; --TO_DATE('01-03-2013', 'DD-MM-YYYY');

    select count(*)
      into v_count_anul
      from fin_doc_anulado
     where anul_tipo_mov in
           (select deta_tmov_codigo
              from fin_tipo_talo, fin_tipo_talo_deta
             where deta_tipo_codi = v_talo_tipo_codi)
       and anul_suc = p_suc
       and anul_nro_doc = (v_nume - 1)
       and anul_empr = 1
       and trunc(anul_fec_doc) >= trunc(sysdate) - 900; --TO_DATE('01-03-2013', 'DD-MM-YYYY');

    if v_count = 0 then
      if v_count_anul = 0 then
        pl_me('Atención!!!!!.. Primero debe procesar el numero..' ||
              to_char(v_nume - 1));
      end if;
    end if;
    --pp_busca_nro_minimo_disp(p_suc, v_talo_tipo_codi, v_mone_codi, v_talo_nume_desd, v_talo_nume_hast, v_nume);
  end if;

  --ahora verificar que el numero no esté cargado en el sistema, o q esté registrado como anulado
  select count(*)
    into v_count2
    from fin_documento
   where doc_tipo_mov in
        (select deta_tmov_codigo
            from fin_tipo_talo, fin_tipo_talo_deta
           where deta_tipo_codi = v_talo_tipo_codi
           and   deta_tmov_codigo = doc_tipo_mov)
     and doc_suc = p_suc
     and doc_nro_doc = (v_nume)
     and doc_mon = v_mone_codi
     and doc_suc_punto_exp = :bdoc.doc_suc_punto_exp
     and doc_punto_exp = :bdoc.doc_punto_exp
     and doc_empr = 1
     and trunc(doc_fec_doc) >= trunc(sysdate) - 365; --TO_DATE('01-03-2013', 'DD-MM-YYYY');

  select count(*)
    into v_count_anul2
    from fin_doc_anulado,
         adre.fin_cier_caja,
         adre.fin_cuenta_bancaria
   where anul_tipo_mov in
         (select deta_tmov_codigo
            from fin_tipo_talo, fin_tipo_talo_deta
           where deta_tipo_codi = v_talo_tipo_codi
           and   deta_tmov_codigo = anul_tipo_mov)
     and anul_suc = p_suc
     and anul_nro_doc = (v_nume)
     and anul_empr = 1
     and anul_cica_clave = cica_clave(+)
     and cica_cta_bco = cta_codigo(+)
     and cta_mon = v_mone_codi
     and anul_suc_punto_exp = :bdoc.doc_suc_punto_exp
     and anul_punto_exp = :bdoc.doc_punto_exp
     and trunc(anul_fec_doc) >= trunc(sysdate) - 365; --TO_DATE('01-03-2013', 'DD-MM-YYYY');

  if v_count2 > 0 or v_count_anul2 > 0 then
    /*pl_me('Atención!!!!!.. El numero..' || to_char(v_nume) ||
          ' ya se encuentra procesado en el sistema');*/
     select max(doc_fec_doc)
        into vfecha
		    from fin_documento
		   where doc_tipo_mov in
		        (select deta_tmov_codigo
		            from fin_tipo_talo, fin_tipo_talo_deta
		           where deta_tipo_codi = v_talo_tipo_codi
		           and   deta_tmov_codigo = doc_tipo_mov)
		     and doc_suc = p_suc
		     and doc_nro_doc = (v_nume)
		     and doc_mon = v_mone_codi
		     and doc_empr = 1
		     and trunc(doc_fec_doc) >= trunc(sysdate) - 365;      
		pl_me('Atención!!!!!.. El numero..' || to_char(v_nume) ||
		          ' ya se encuentra procesado en el sistema' || chr(10)||
		          ' v_count2  ' || v_count2  || chr(10)|| 
		          ' v_count_anul2 ' || v_count_anul2 || chr(10)||
		          ' v_mone_codi ' || v_mone_codi|| chr(10)||
		          ' p_suc ' || p_suc || chr(10) ||
		          ' vfecha ' || vfecha);
  end if;

end;

PROCEDURE PP_ABRIR_FORM (p_form in varchar2, p_programa_desc in varchar2, POSICION_X IN NUMBER, POSICION_Y IN NUMBER)	 IS

  pl_id ParamList;
  aud_clave number;

BEGIN 


--*
  pl_id := GET_PARAMETER_LIST('ParamTemp');
  IF NOT ID_NULL(pl_id) THEN
     DESTROY_PARAMETER_LIST('ParamTemp');
  END IF;
  pl_id := CREATE_PARAMETER_LIST('ParamTemp');
  IF ID_NULL(pl_id) THEN
    pl_me('Error al crear lista de parametros!');
  END IF;
--*
break;
--*
  ADD_PARAMETER(PL_ID,'P_EMPRESA'       ,TEXT_PARAMETER,TO_CHAR(:PARAMETER.P_EMPRESA));  
  ADD_PARAMETER(PL_ID,'P_DESC_EMPRESA'  ,TEXT_PARAMETER, :PARAMETER.P_DESC_EMPRESA);
  ADD_PARAMETER(PL_ID,'P_SUCURSAL'      ,TEXT_PARAMETER,TO_CHAR(:PARAMETER.P_SUCURSAL));
  ADD_PARAMETER(PL_ID,'P_DESC_SUCURSAL' ,TEXT_PARAMETER, :PARAMETER.P_DESC_SUCURSAL);
  ADD_PARAMETER(PL_ID,'P_IMPRESORA'     ,TEXT_PARAMETER, :PARAMETER.P_IMPRESORA);  
  ADD_PARAMETER(PL_ID,'P_DOC_FORM_PAGO' ,TEXT_PARAMETER, :BDOC.FORM_PAGO_DESC );    


--*
  ADD_PARAMETER(PL_ID,'X_POS',TEXT_PARAMETER, POSICION_X);
  ADD_PARAMETER(PL_ID,'Y_POS',TEXT_PARAMETER, POSICION_Y);  

  ADD_PARAMETER(pl_id,'P_DOC_CLAVE'   ,TEXT_PARAMETER,  :BCUO.CUO_CLAVE_DOC);
  ADD_PARAMETER(pl_id,'P_CUO_FEC_VTO' ,TEXT_PARAMETER, TO_CHAR(:BCUO.CUO_FEC_VTO, 'DD/MM/YYYY'));
  ADD_PARAMETER(pl_id,'P_MON_RECIBO'  ,TEXT_PARAMETER,  :BDOC.DOC_MON);
  ADD_PARAMETER(pl_id,'P_DOC_CTA_BCO' ,TEXT_PARAMETER,  :BDOC.DOC_CTA_BCO);
  ADD_PARAMETER(pl_id,'P_CLI_CODIGO'  ,TEXT_PARAMETER,  :BDOC.DOC_CLI);
  --ADD_PARAMETER(pl_id,'P_IMPRESORA'   ,TEXT_PARAMETER,  :PARAMETER.P_IMPRESORA);
  ADD_PARAMETER(pl_id,'P_IMPORTE_INTERES',TEXT_PARAMETER,  :BCUO.S_IMP_INTERES);
--*
  ADD_PARAMETER(pl_id,'P_PROGRAMA'      ,TEXT_PARAMETER, p_form);
  ADD_PARAMETER(pl_id,'P_DESC_PROGRAMA' ,TEXT_PARAMETER, p_programa_desc);  


  --CALL_FORM (p_form, HIDE, NO_REPLACE, NO_QUERY_ONLY, PL_ID);
  --CALL_FORM (p_form, NO_HIDE, NO_REPLACE, NO_QUERY_ONLY, PL_ID);
  OPEN_FORM (p_form, ACTIVATE, SESSION, PL_ID);


END;

PROCEDURE pp_sumar_intereses_marcados IS
vregistro   number;
vsum_int		number(14,4);
BEGIN
  if nvl(:bcuo.s_marca,'.') = 'X' then 
  	vregistro := :system.cursor_record;
  	first_record;
  	loop
  		if nvl(:bcuo.s_marca,'.') = 'X' then 
  			vsum_int := nvl(vsum_int,0) + nvl(:bcuo.s_imp_interes,0);
  		end if;
  	exit when :system.last_record = 'TRUE';
  	next_record;
  	end loop;
  	:bdoc.s_int_a_cobrar := vsum_int;
  	first_record;
  	go_record(vregistro);
  end if;
END;

PROCEDURE PP_IMPRIMIR_RECIBO IS
  pl_id   PARAMLIST;
  V_ALERT NUMBER;
  SALIR EXCEPTION;
  vArchivo VARCHAR2(200);

BEGIN

  pl_id := GET_PARAMETER_LIST('ParamTemp');
  IF NOT ID_NULL(pl_id) THEN
    DESTROY_PARAMETER_LIST('ParamTemp');
  END IF;
  pl_id := CREATE_PARAMETER_LIST('ParamTemp');
  IF ID_NULL(pl_id) THEN
    PL_EXHIBIR_ERROR('Error al crear lista de parametros!');
  END IF;

  IF :PARAMETER.P_IMP_RECIBO IS NOT NULL THEN

		  ADD_PARAMETER(pl_id, 'RUNDEBUG', TEXT_PARAMETER, 'NO');
		  ADD_PARAMETER(PL_ID, 'P_CLAVE_RECIBO', TEXT_PARAMETER, :BDOC.DOC_CLAVE);  
		  ADD_PARAMETER(PL_ID, 'DESFORMAT', TEXT_PARAMETER, 'HP_PCL'); --- SE ENVIA ESTE PARAMETRO PARA QUE USE EL ARCHIVO .PRT CORRESPONDIENTE.
		  ADD_PARAMETER(PL_ID, 'PARAMFORM', TEXT_PARAMETER, 'NO');
		  ADD_PARAMETER(PL_ID, 'DESTYPE', TEXT_PARAMETER, 'PRINTER');

		  IF :PARAMETER.P_IMP_RECIBO NOT IN ('DEFAULT', 'PREDETERMINADO') THEN
		  	ADD_PARAMETER(PL_ID,'DESNAME'         , TEXT_PARAMETER , :PARAMETER.P_IMP_RECIBO);
		  END IF;

		  IF :PARAMETER.P_PATH_IMP_FACTURA IS NULL THEN
				PL_ME('No esta configurada la impresora en el registro. Avisar al Departamento de Informática.');
			END IF;
		  IF "ADRE"."F_CONEX_USUARIO"('USERENV', 'IP_ADDRESS') in ('10.16.3.31', '10.16.0.25') THEN
		  	ADD_PARAMETER(pl_id,'DESNAME'  ,TEXT_PARAMETER, :PARAMETER.P_PATH_IMP_FACTURA);
		  END IF;
		  RUN_PRODUCT(REPORTS, 'FINI018.RDF', SYNCHRONOUS, BATCH, FILESYSTEM, pl_id, NULL);

  ELSE
	   	vArchivo := 'C:\TEMP\REC_'||:BDOC.DOC_NRO_DOC|| TO_CHAR(SYSDATE, 'DDMMYYYYHH24MISS') || '.PDF';

	 	ADD_PARAMETER(pl_id, 'P_CONF_EMPR' , TEXT_PARAMETER , NVL(:PARAMETER.P_EMPRESA, '1'));  
	  ADD_PARAMETER(PL_ID, 'P_CLAVE_RECIBO', TEXT_PARAMETER, :BDOC.DOC_CLAVE);  
	  ADD_PARAMETER(pl_id, 'RUNDEBUG' , TEXT_PARAMETER    , 'No');  
	  ADD_PARAMETER(pl_id, 'PARAMFORM', TEXT_PARAMETER    , 'No');    
	  ADD_PARAMETER(pl_id, 'DESFORMAT', TEXT_PARAMETER    , 'PDF');
	  ADD_PARAMETER(pl_id, 'DESTYPE'  ,TEXT_PARAMETER     , 'File');
	  ADD_PARAMETER(pl_id, 'DESNAME'  ,TEXT_PARAMETER     ,  vArchivo);  
	  RUN_PRODUCT(REPORTS, 'FINI018.RDF', SYNCHRONOUS, BATCH  ,FILESYSTEM,pl_id,NULL);
	  Destroy_Parameter_List( pl_id );    
	  PP_ABRIR_ARCHIVO(vArchivo)     ;  
	END IF;

EXCEPTION
  WHEN SALIR THEN
    NULL;

END;

PROCEDURE PP_OBTENER_POSICION_ITEM(P_WINDOW_ACTUAL IN VARCHAR2, POSICION_X OUT NUMBER, POSICION_Y OUT NUMBER ) IS


ITEMPOSX         NUMBER(8);
ITEMPOSY				 NUMBER(8);
WINDOWPRINCIPALX NUMBER(8);
WINDOWPRINCIPALY NUMBER(8);


BEGIN

	/* OBTENER LA POSICION X E Y DEL CANVAS PRINCIPAL */    
    WINDOWPRINCIPALX	:=        TO_NUMBER( GET_WINDOW_PROPERTY(P_WINDOW_ACTUAL, X_POS  )); 
    WINDOWPRINCIPALY	:=        TO_NUMBER( GET_WINDOW_PROPERTY(P_WINDOW_ACTUAL, Y_POS  ));

  /* OBTENER LA POSICION X E Y DEL BLOQUE.ITEM QUE SE DESEA USAR COMO FOCO */
    ITEMPOSX        :=        TO_NUMBER( GET_ITEM_PROPERTY(:SYSTEM.CURSOR_ITEM, X_POS)) ;
    ITEMPOSY        :=        TO_NUMBER( GET_ITEM_PROPERTY(:SYSTEM.CURSOR_ITEM, Y_POS)) ;

 /* ESTABLECER LA NUEVA POSICION DE LA VENTANA AUXILIAR RESPECTO DE LA NUEVA POSICION DE CANVAS PRINCIPAL */
 /* CON ESTA OPERACION LA VENTANA AUXILIAR SIEMPRE APARECERÁ EN LA MISMA POSICION EN CASO QUE EL USUARIO HAYA MOVIDO DE LUGAR LA VENTANA PRINCIPAL */      

     POSICION_X  := WINDOWPRINCIPALX + ITEMPOSX ;
     POSICION_Y  := WINDOWPRINCIPALY + ITEMPOSY ;


END;

FUNCTION FP_EXTRAER_CADENA_CLAVE(pCadena IN VARCHAR2, pValorDeseado in varchar2, p_separador in varchar2) return varchar is



  vCadena        varchar2(256);
  vCadenaCortada varchar2(256);

  vPos1       number(3);
  vPos2       number(3);
  vResultado  varchar2(21);


begin

vPos1           :=   INSTR(pCadena , pValorDeseado||p_separador) ;
vCadenaCortada  :=  SUBSTR(pCadena , vPos1);
vPos2           :=   INSTR(vCadenaCortada,',') ;

if vPos2 > 1 then
  vPos2 := vPos2-1 ;
end if;
vResultado      := SUBSTR(vCadenaCortada, 1, vPos2);

return vResultado;

END;

PROCEDURE PP_VALIDAR_CIERRE_CAJA IS

vCICA_ESTA VARCHAR2(1);
BEGIN

	SELECT CICA_ESTA
	 INTO  vCICA_ESTA
   FROM  ADRE.FIN_CIER_CAJA
  WHERE  CICA_CTA_BCO =:BDOC.DOC_CTA_BCO
   AND   CICA_FECH    =:BDOC.DOC_FEC_OPER ;


   IF vCICA_ESTA='C' THEN
    MESSAGE('La caja '||:BDOC.DOC_CTA_BCO||' del '||:BDOC.S_DOC_FEC_OPER||' está cerrada.');   
    RAISE FORM_TRIGGER_FAILURE;
   END IF;

   EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
             WHEN TOO_MANY_ROWS THEN 
   	          MESSAGE('Cierre de caja duplicado en fecha '||:BDOC.S_DOC_FEC_OPER||' caja '||:BDOC.DOC_CTA_BCO);   
              RAISE FORM_TRIGGER_FAILURE;


END;

PROCEDURE PP_MOSTRAR_BCO(codigo in number, descripcion in out varchar2) 
 IS
BEGIN

  SELECT BCO_DESC
    INTO descripcion
    FROM FIN_BANCO
   WHERE BCO_CODIGO = codigo;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    descripcion := null;
    PL_EXHIBIR_ERROR('Banco inexistente');
END;

PROCEDURE PP_MOSTRAR_FORMA_PAGO (P_FP_CLAVE IN NUMBER, BLOQUE_ITEM IN VARCHAR2) IS

vSTRING VARCHAR2(60);

BEGIN

  	SELECT FP_DESCRIPCION 
  	  INTO vSTRING
		  FROM ADRE.FIN_FORMA_PAGO
		 WHERE NVL(FP_ACTIVO, 'N') = 'S'
		   AND NVL(FP_RECIBO, 'N') = 'S'
		   AND FP_CLAVE = P_FP_CLAVE ;

	  COPY( vSTRING, BLOQUE_ITEM );

EXCEPTION WHEN NO_DATA_FOUND THEN
	COPY( '', BLOQUE_ITEM ); 
	pl_mm('Medio de pago inexistente. Presione F9 para ver lista.');
  RAISE FORM_TRIGGER_FAILURE ;

END;

PROCEDURE pp_validar_bloque_bmp IS

vMENSAJE varchar2(150);

BEGIN

  go_block('BMP');
  first_record ;

  if nvl(:bmp.mp_sum_importe,0) <> :bdoc.doc_neto_exen_mon then
   go_block('bcuo');
   first_record ;
   pl_mm('Error1, La suma de importes del MEDIO DE PAGO no es igual al total del recibo. ');  
   raise form_trigger_failure;
  end if;


  loop  

  if :bmp.mp_medio_pago = 1 then --> Efectivo  	     
			:bmp.mp_nro_referencia   := null;
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;   

	elsif :bmp.mp_medio_pago in (2,3) then --> Tarjeta Debito / Credito
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;  

	elsif :bmp.mp_medio_pago = 7 then --> Transferencia Bancaria			
			:bmp.mp_cheque_nro       := null;			
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;		

	elsif :bmp.mp_medio_pago not in (4,5) then --> Cheques
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;										
	end if;


  if :bmp.mp_medio_pago is not null and :bmp.mp_importe < 0  then
        vMENSAJE := 'Error2, El importe de pago '||:bmp.fp_descripcion||' no puede ser negativo.';
        exit;

	  elsif :bmp.mp_medio_pago is not null and :bmp.mp_importe = 0  then
        vMENSAJE := 'Error3, El importe de pago '||:bmp.fp_descripcion||' no puede ser 0 (cero).';	
        exit;

	  elsif :bmp.mp_medio_pago is not null and :bmp.mp_importe is null  then
        vMENSAJE := 'Error4, El importe de pago '||:bmp.fp_descripcion||' no puede quedar vacío.';		    
        exit;

	  elsif :bmp.mp_medio_pago in (2,3) and :bmp.mp_importe is not null and :bmp.mp_nro_referencia is null  then 
       vMENSAJE := 'Error5, El medio de pago '||:bmp.fp_descripcion||' requiere el Nro de referencia de la operación.';		    
        exit;        

	  elsif :bmp.mp_medio_pago = 7 and :bmp.mp_importe is not null and :bmp.mp_banco_emisor is null  then 
        vMENSAJE := 'Error6, El medio de pago '||:bmp.fp_descripcion||' requiere que ingrese el banco emisor.';		    
        exit;        

	  elsif :bmp.mp_medio_pago = 7 and :bmp.mp_importe is not null and :bmp.mp_nro_referencia is null  then 
        vMENSAJE := 'Error7, El medio de pago '||:bmp.fp_descripcion||' requiere el Nro de referencia de la operación.';		    
        exit;     

	  elsif :bmp.mp_medio_pago = 7 and :bmp.mp_importe is not null and :bmp.mp_nro_referencia is not null and :bmp.mp_fecha_cheque is null then 
        vMENSAJE := 'Error8, El medio de pago '||:bmp.fp_descripcion||' requiere fecha de la transferencia.';		    
        exit;   

	  elsif :bmp.mp_medio_pago in (4,5) and :bmp.mp_importe is not null and :bmp.mp_banco_emisor is null  then --> Cheque Día y Diferido
        vMENSAJE := 'Error9, El medio de pago '||:bmp.fp_descripcion||' requiere que ingrese el banco emisor.';		    
        exit;           

	  elsif :bmp.mp_medio_pago in (4,5) and :bmp.mp_importe is not null and :bmp.mp_cheque_nro is null then  --> Cheque Día y Diferido
        vMENSAJE := 'Error10, Para medio de pago '||:bmp.fp_descripcion||' debe ingresar el número de cheque.';
	      exit; 
	  elsif :bmp.mp_medio_pago in (4,5) and :bmp.mp_importe is not null and :bmp.mp_fecha_cheque is null then --> Cheque Día y Diferido
        vMENSAJE := 'Error11, Para medio de pago '||:bmp.fp_descripcion||' debe ingresar fecha del cheque.';
        exit;

	  elsif :bmp.mp_medio_pago in (4,5) and :bmp.mp_importe is not null and :bmp.mp_fecha_cheque is not null and 
	  	    :bmp.mp_fecha_cheque_vto is null then --> Cheque Día / Diferido        
        vMENSAJE := 'Error12, Para medio de pago '||:bmp.fp_descripcion||' debe ingresar fecha de vto. del cheque.';
        exit;        

	  elsif :bmp.mp_medio_pago in (4,5) and :bmp.mp_importe is not null and :bmp.mp_fecha_cheque is not null and 
	  	    :bmp.mp_fecha_cheque_vto is not null and :bmp.mp_librador_cheque is null  then --> Cheque Día / Diferido        
        vMENSAJE := 'Error13, Para medio de pago '||:bmp.fp_descripcion||' debe ingresar librador del cheque.';
        exit;        

   end if;  

   if :bmp.mp_medio_pago is null and :bmp.mp_importe is not null then
      vMENSAJE := 'Error14, Falta ingresar el MEDIO DE PAGO.';
      exit;
   end if;    

  exit when :system.last_record = 'TRUE';
  next_record ;

  end loop;  

  if vMENSAJE is not null then  	
    pl_mm(vMENSAJE);
    raise form_trigger_failure;
  end if;

  --> Si en detalle existe un solo medio de pago este debe coincidir con la forma de pago de cabecera.
  if :system.cursor_record = 1 and (:bdoc.form_pago <> :bmp.mp_medio_pago ) and :bmp.mp_medio_pago <> 1 then 
    pl_mm('Error15, El MEDIO DE PAGO '||:bmp.fp_descripcion||' no coincide con la FORMA DE PAGO '||:bdoc.form_pago_desc);
    raise form_trigger_failure;
  end if;  

  if :system.cursor_record > 5 then
    pl_mm('La dimensión del recibo acepta hasta un máximo de 5 medios de pagos.');
    raise form_trigger_failure;
  end if;  

END;

FUNCTION FP_DEVUELVE_FECHA (PARAMETRO_FECHA IN VARCHAR2) RETURN DATE IS

  v_FECHA       VARCHAR2(20);
  v_LENGTH         NUMBER(3);
  DIA_MES_ANHO         DATE ;

BEGIN

     v_FECHA  :=   REPLACE(PARAMETRO_FECHA, '-','') ;
     v_FECHA  :=   REPLACE(v_FECHA, '/','') ;
     v_LENGTH :=   LENGTH (REPLACE( REPLACE(PARAMETRO_FECHA, '-','') , '/', ''));


	   IF v_LENGTH  = 1 THEN
	      DIA_MES_ANHO := TO_DATE('0'||v_FECHA, 'DD');
	   END IF; 

	   IF v_LENGTH  = 2 THEN
	      DIA_MES_ANHO := TO_DATE(v_FECHA||TO_CHAR(:PARAMETER.P_SYSDATE, 'MMYYYY') , 'DDMMYYYY');
     END IF;

	   IF v_LENGTH  = 4 THEN
	      DIA_MES_ANHO := TO_DATE(v_FECHA||TO_CHAR(:PARAMETER.P_SYSDATE, 'YYYY') , 'DDMMYYYY');
     END IF; 

	   IF v_LENGTH  = 6 THEN
	      DIA_MES_ANHO := TO_DATE(v_FECHA , 'DDMMYY');
	   END IF; 

	   IF v_LENGTH  = 8 THEN
	      DIA_MES_ANHO := TO_DATE(v_FECHA , 'DDMMYYYY');      
	   END IF; 	         

  RETURN (  DIA_MES_ANHO ) ; 

EXCEPTION WHEN NO_DATA_FOUND THEN	   
	   PL_EXHIBIR_ERROR(SQLERRM);

  	      WHEN OTHERS THEN
  	 PL_EXHIBIR_ERROR(SQLERRM);

END;

