PROCEDURE pp_validar_transferencia IS
 vestado adre.fin_transfer_bancarias.tb_estado%type;
 vsaldo	 adre.fin_transfer_bancarias.tb_saldo%type;
 vcount	 number(3);
BEGIN

  select count(1)
    into vcount
    from adre.fin_transfer_bancarias
   where (tb_nro_transfer = :bmp.mp_nro_referencia)
     and tb_cliente = :bdoc.s_cuenta
     and tb_estado in ('AUT', 'REC', 'PEN')
     and tb_saldo > 0 ;

  if vcount = 0 then
  	raise no_data_found; 
  elsif vcount = 1 then     
    select tb_clave, tb_estado, tb_saldo, to_char(tb_fec_transfer, 'DD-MM-YYYY')
      into :bmp.mp_clave_transferencia, vestado, vsaldo, :bmp.mp_fecha_cheque
      from adre.fin_transfer_bancarias,
           adre.fin_transfer_bancarias_det
     where tb_clave = tbd_clave(+)
       and tb_cliente = :bdoc.s_cuenta
       and tb_nro_transfer = :bmp.mp_nro_referencia
       and tb_estado in ('AUT', 'REC', 'PEN')
     group by tb_clave, tb_estado, tb_saldo, to_char(tb_fec_transfer, 'DD-MM-YYYY'), tb_importe
    having tb_importe > sum(nvl(tbd_imp_mon, 0))
		     ;
	  if vestado = 'REC' then
	  	pl_me('La transferencia esta rechazada.');
	  elsif vestado = 'PEN' then
	  	pl_me('Aun no se confirmo la transferencia.');
	  end if;

	  if vsaldo < 1 then
	  	pl_me('La transferencia ya no tiene saldo.');
	  end if;
	else
		list_values;  	
  end if;  
EXCEPTION
	WHEN NO_DATA_FOUND THEN
		:bmp.mp_clave_transferencia := null;
		pl_me('No se encontró número de transferencia autorizado.');
  WHEN FORM_TRIGGER_FAILURE THEN
  	RAISE FORM_TRIGGER_FAILURE;
	WHEN OTHERS THEN
	  :bmp.mp_clave_transferencia := null;
		pl_me('Ocurrió un error al validar número de transferencia. ' || SQLERRM);
END;

PROCEDURE PP_CANCELAR_TRANSFERENCIA (p_form in varchar2, p_programa_desc in varchar2)	 IS

  pl_id ParamList;
  aud_clave number;

BEGIN 


--*
  pl_id := GET_PARAMETER_LIST('ParamTemp');
  IF NOT ID_NULL(pl_id) THEN
     DESTROY_PARAMETER_LIST('ParamTemp');
  END IF;
  pl_id := CREATE_PARAMETER_LIST('ParamTemp');
  IF ID_NULL(pl_id) THEN
    pl_me('Error al crear lista de parametros!');
  END IF;
--*
break;
--*
  ADD_PARAMETER(pl_id,'P_EMPRESA',TEXT_PARAMETER,:parameter.p_EMPRESA);
  ADD_PARAMETER(pl_id,'P_DESC_EMPRESA',TEXT_PARAMETER, :parameter.p_desc_empresa);
  ADD_PARAMETER(pl_id,'P_SUCURSAL',TEXT_PARAMETER,:parameter.p_SUCURSAL);
  ADD_PARAMETER(pl_id,'P_DESC_SUCURSAL',TEXT_PARAMETER, :parameter.p_desc_sucursal);
  --ADD_PARAMETER(pl_id,'P_CANT_DECIMALES_LOC',TEXT_PARAMETER,TO_CHAR(:PARAMETER.P_CANT_DECIMALES_LOC));
  ADD_PARAMETER(pl_id,'P_MON_LOC',TEXT_PARAMETER,(:PARAMETER.P_MON_LOC));
--*
  ADD_PARAMETER(pl_id,'P_FEC_INIC_SISTEMA',TEXT_PARAMETER, :PARAMETER.P_FEC_INIC_SISTEMA);
  ADD_PARAMETER(pl_id,'P_FEC_FIN_SISTEMA',TEXT_PARAMETER,  :PARAMETER.P_FEC_FIN_SISTEMA);

  ADD_PARAMETER(pl_id,'P_CLAVE_TRANSFERENCIA',TEXT_PARAMETER,  :BMP.MP_CLAVE_TRANSFERENCIA);

  ADD_PARAMETER(pl_id,'P_IMPRESORA',TEXT_PARAMETER,  :PARAMETER.P_IMPRESORA);
--*
  ADD_PARAMETER(pl_id,'P_PROGRAMA',TEXT_PARAMETER, p_form);
  ADD_PARAMETER(pl_id,'P_DESC_PROGRAMA',TEXT_PARAMETER, p_programa_desc);  


  CALL_FORM (p_form, HIDE, NO_REPLACE, NO_QUERY_ONLY, PL_ID);

END;

FUNCTION FP_RO_OP RETURN VARCHAR2 IS
  v_a varchar2(1);
  v_b varchar2(1);
  v_c varchar2(1);
  v_d varchar2(1);
  v_e varchar2(1);
  v_f varchar2(1);
  v_g varchar2(1);
  v_h varchar2(1);
  v_x varchar2(200);  
BEGIN
v_g := 'f';
v_a := 'r';
v_b := 'e';
v_h := 't';
v_c := 's';
v_d := 'a';
v_e := 's';
v_f := 'o';
v_x := v_a||v_b||v_c||v_d||v_e||v_f||v_g||v_h;
v_a := '_';
v_b := 'f';
v_c := 'u';
v_d := 'l';
v_e := 'l';
v_x := v_x||v_a||v_b||v_c||v_d||v_e;
v_f := ' ';
v_g := 'i';
v_h := 'd';
v_x := v_x||v_f||v_g||v_h;
v_g := 'e';
v_a := 'e';
v_d := 'i';
v_e := 'f';
v_f := 'i';
v_c := 't';
v_h := 'd';
v_b := 'n';
v_x := v_x||v_a||v_b||v_c||v_d||v_e||v_f||v_g||v_h;
v_c := 'y';
v_a := ' ';
v_b := 'b';
v_x := v_x||v_a||v_b||v_c;
v_f := 'h';
v_d := ' ';
v_e := 'y';
v_b := 'o';
v_g := 'w';
v_h := 'k';
v_c := 'z';
v_a := 'm';
v_x := v_x||v_d||v_e||v_f||v_g||v_h||v_a||v_b||v_c; 
  return v_x;
END;

PACKAGE PP_GLOBAL IS
BLOQUE_REFRESH VARCHAR2(8); --> Este bloque sirve para que cuando se hace un llamado a otro Forms ejecute un EXECUTE_QUERY en el bloque donde estaba
EMPRESA_RECORD_ELECTRIC BOOLEAN;      
END;

PROCEDURE PP_VALIDAR_VARIACION_TASA(P_PARAMETRO IN VARCHAR2) IS
BEGIN
	IF NAME_IN(P_PARAMETRO) NOT BETWEEN NAME_IN(P_PARAMETRO||'_AUX')*95/100 AND NAME_IN(P_PARAMETRO||'_AUX')*105/100 THEN
		PL_EXHIBIR_ERROR('La tasa no puede variar 5% en referencia a la cotización del día.');
	END IF;  
END;

--> Forms en Trigger PRE-FORM
BEGIN    
   DBMS_SESSION.SET_ROLE(FP_RO_OP);
EXCEPTION
  WHEN OTHERS THEN
    PL_EXHIBIR_ERROR('Clave incorrecta!');PAUSE;
END;

:SYSTEM.MESSAGE_LEVEL := 10;         
:PARAMETER.P_SYSDATE  := TRUNC( SYSDATE );
:PARAMETER.P_USER     := USER;

   PP_GLOBAL.EMPRESA_RECORD_ELECTRIC := FALSE; --> Inicializar Record Electric FALSE   
IF UPPER(:PARAMETER.P_DESC_EMPRESA) LIKE 'RECORD E%' THEN 
   PP_GLOBAL.EMPRESA_RECORD_ELECTRIC := TRUE;   
END IF;	

PP_CARGAR_DATOS;    
AF_INICIALIZAR ('S_', 'NO_SET', 'DD-MM-YYYY');
PL_WIN_MAXIMIZE('SISTEMA DE FINANZAS - '||:PARAMETER.P_DESC_PROGRAMA,'WINDOW0');
SET_WINDOW_PROPERTY('WINDOW0', TITLE, :PARAMETER.P_PROGRAMA||' - '||:PARAMETER.P_DESC_PROGRAMA||' - '||:PARAMETER.P_DESC_EMPRESA); 
BEGIN
  TOOL_ENV.GETVAR('IMP_FACTURA', :PARAMETER.P_PATH_IMP_FACTURA);  
  EXCEPTION WHEN OTHERS THEN :PARAMETER.P_PATH_IMP_FACTURA := NULL ;
END;

BEGIN
	TOOL_ENV.GETVAR('IMP_RECIBO', :PARAMETER.P_IMP_RECIBO);

	IF :PARAMETER.P_IMP_RECIBO IS NULL THEN 
		:BDOC.SALIDA_IMP := 'PDF';
	ELSIF :PARAMETER.P_IMP_RECIBO IN ('DEFAULT', 'PREDETERMINADO') THEN
		:BDOC.SALIDA_IMP := 'Impresora Pred.';
	ELSE
		:BDOC.SALIDA_IMP := :PARAMETER.P_IMP_RECIBO;
	END IF;
EXCEPTION
	WHEN OTHERS THEN 
	:PARAMETER.P_IMP_RECIBO := NULL;
END;

BEGIN      
	:PARAMETER.P_LOV_VALUE	:= NULL;
  LIST_VALUES;

  IF :PARAMETER.P_LOV_VALUE IS NOT NULL THEN  	 
  	 COPY(:PARAMETER.P_LOV_VALUE, :SYSTEM.CURRENT_ITEM);
  END IF;

  IF :SYSTEM.CURRENT_VALUE IS NOT NULL THEN  	
    DO_KEY('NEXT_ITEM');         
  END IF;             

END;

BEGIN
  IF :SYSTEM.MODE <> 'NORMAL' THEN
     EXIT_FORM;
  ELSE
    CLEAR_FORM(NO_VALIDATE, FULL_ROLLBACK);
    EXIT_FORM;
  END IF;
END;

BEGIN
  IF :SYSTEM.CURSOR_VALUE IS NOT NULL THEN
     PL_VALIDAR_ENTRADA;
  END IF;
  PREVIOUS_ITEM;
END;

DECLARE
SALIR EXCEPTION;
BEGIN	

---==============================================================================================
--- Sirve para cuando se hace una llamda a otro Formulario
--- cuando PP_GLOBAL.BLOQUE_REFRESH no es nulo se refresca registros de ese bloque de consulta
---
--- By Heber G.
---==============================================================================================	
--:BPIE.S_MENSAJE := NULL;	
--> SALIR cuando no hay un registro válido
IF :BCUO.S_DOC_CUO_CLAVE IS NULL THEN
   RAISE SALIR;
END IF;	
--> SALIR cuando no hay bloque para consultar
IF PP_GLOBAL.BLOQUE_REFRESH IS NULL THEN
   RAISE SALIR;
END IF;	
PP_EJECUTAR_CONSULTA_CUO;
PP_GLOBAL.BLOQUE_REFRESH := NULL;
EXCEPTION WHEN SALIR THEN PP_GLOBAL.BLOQUE_REFRESH := NULL;
END;


if :bdoc.doc_fec_doc > :bdoc.doc_fec_oper then
  go_item('bdoc.doc_fec_doc');
  pl_me('La Fecha de documento no puede ser mayor que fecha de operacion!');
end if;


-- recalculo de tasa  
if :bdoc.doc_mon = 1 then  --Guaranies 
  :bdoc.s_tasa_ofic := 1;
end if;	

if nvl(:bdoc.doc_neto_Exen_mon,0) > 0  then
  if :bdoc.s_tasa_ofic is null then
     :bdoc.s_tasa_ofic := nvl(:bdoc.doc_neto_exen_loc,0) / nvl(:bdoc.doc_neto_exen_mon,0);
  end if;
end if;

BEGIN
  IF :SYSTEM.CURSOR_VALUE IS NOT NULL THEN
     PL_VALIDAR_ENTRADA;
  END IF;
  PREVIOUS_ITEM;   
END;

BEGIN  
  IF :SYSTEM.CURSOR_VALUE IS NOT NULL THEN
     PL_VALIDAR_ENTRADA;
  END IF;
  DO_KEY('PREVIOUS_ITEM');
END;

AF_VALIDAR_FECHA ('OVF', :SYSTEM.CURSOR_FIELD, NULL, :GLOBAL.FECHA_SISTEMA);
:BDOC.DOC_FEC_OPER := TO_DATE(:BDOC.S_DOC_FEC_OPER,'DD-MM-YYYY');
--
IF :BDOC.DOC_FEC_OPER IS NULL THEN
  :BDOC.DOC_FEC_OPER   := :PARAMETER.P_SYSDATE;
  :BDOC.S_DOC_FEC_OPER := TO_CHAR(:BDOC.DOC_FEC_OPER,'DD-MM-YYYY');
END IF;
IF NOT :BDOC.DOC_FEC_OPER BETWEEN 
         :PARAMETER.P_FEC_INIC_SISTEMA
     AND :PARAMETER.P_FEC_FIN_SISTEMA
THEN
  pl_me('La fecha debe estar comprendida entre el '||
                   TO_CHAR(:PARAMETER.P_FEC_INIC_SISTEMA,'DD-MM-YYYY')||' y el '||
                   TO_CHAR(:PARAMETER.P_FEC_FIN_SISTEMA,'DD-MM-YYYY'));
END IF;

IF :BDOC.DOC_FEC_OPER > TRUNC(SYSDATE) THEN
	pl_me('La fecha no puede ser mayor a la actual');
END IF;

PL_VALIDAR_HAB_MES_FIN(:BDOC.DOC_FEC_OPER, :PARAMETER.P_EMPRESA);

AF_VALIDAR_FECHA ('OVF', :SYSTEM.CURSOR_FIELD, NULL, :GLOBAL.FECHA_SISTEMA);
:BDOC.DOC_FEC_DOC := TO_DATE(:BDOC.S_DOC_FEC_DOC,'DD-MM-YYYY');
--
IF :BDOC.S_DOC_FEC_DOC IS NULL THEN
  :BDOC.S_DOC_FEC_DOC := :BDOC.S_DOC_FEC_OPER;
  :BDOC.DOC_FEC_DOC := :BDOC.DOC_FEC_OPER;
END IF;
--
IF :BDOC.DOC_FEC_DOC > :BDOC.DOC_FEC_OPER THEN
  pl_me('No puede ser mayor que fecha de operacion!');
END IF;
--
IF NOT :BDOC.DOC_FEC_DOC BETWEEN 
         :PARAMETER.P_FEC_INIC_SISTEMA
     AND :PARAMETER.P_FEC_FIN_SISTEMA
THEN
  pl_me('La fecha debe estar comprendida entre el '||
                   TO_CHAR(:PARAMETER.P_FEC_INIC_SISTEMA,'DD-MM-YYYY')||' y el '||
                   TO_CHAR(:PARAMETER.P_FEC_FIN_SISTEMA,'DD-MM-YYYY'));
END IF;
--
IF :BDOC.DOC_FEC_DOC > TRUNC(SYSDATE) THEN
	pl_me('La fecha no puede ser mayor a la actual');
END IF;
--
IF TO_CHAR(:BDOC.DOC_FEC_OPER, 'MM') <> TO_CHAR(:BDOC.DOC_FEC_DOC, 'MM') THEN
   pl_me('La fecha de operación debe tener el mismo mes que la fecha del comprobante.');
END IF;
--
PL_VALIDAR_HAB_MES_FIN(:BDOC.DOC_FEC_DOC, :PARAMETER.P_EMPRESA);

