    entonces se deberá poder navegar sobre importes locales */
    :bdoc.doc_neto_exen_loc := null;
    set_item_property('bdoc.doc_neto_exen_loc', enabled,property_true);
    set_item_property('bdoc.doc_neto_exen_loc', navigable,property_true);
else
    set_item_property('bdoc.doc_neto_exen_loc', enabled,property_false);
   :bdoc.doc_neto_exen_loc := round(:bdoc.doc_neto_exen_mon* :bdoc.s_tasa_ofic,:parameter.p_cant_decimales_loc);      
end if;

IF ADRE.BUSCA_PERMISO(:PARAMETER.P_PROGRAMA, USER, 'PERMITE_VARIACION_TASA') = 'N' THEN
	PP_VALIDAR_VARIACION_TASA('BDOC.S_TASA_OFIC');
END IF;

