if :bdoc.doc_neto_exen_mon is null then
	:bdoc.doc_neto_exen_mon := 0;        
end if;

if nvl(:bdoc.doc_neto_exen_mon,0) < 0 then
  :bdoc.doc_neto_Exen_mon := 0;
end if;

:bdoc.doc_neto_exen_loc :=    round(nvl(:bdoc.doc_neto_exen_mon,0)  * nvl(:bdoc.s_tasa_ofic,1), :parameter.p_cant_decimales_loc);

if :bdoc.doc_neto_exen_loc is null then
	:bdoc.doc_neto_exen_loc := 0;
end if;

if nvl(:bdoc.doc_neto_exen_loc,0) < 0 then
  :bdoc.doc_neto_Exen_loc := 0;
end if;

if nvl(:bdoc.doc_neto_exen_mon ,0) > 0 then
	if nvl(:bdoc.doc_mon,0) <> nvl(:parameter.p_mon_loc,0) then
	  :bdoc.s_tasa_ofic := :bdoc.doc_neto_exen_loc / :bdoc.doc_neto_exen_mon;
	else
	  :bdoc.s_tasa_ofic        := 1;
	  :bdoc.doc_neto_exen_loc  := :bdoc.doc_neto_exen_mon;
	end if;
else
  :bdoc.doc_neto_exen_loc := 0;		
end if;

if :bdoc.doc_mon  = :parameter.p_mon_loc then
  :bdoc.s_tasa_ofic        := 1;
  :bdoc.doc_neto_exen_loc  := :bdoc.doc_neto_exen_mon;
end if;

declare
    cursor primary_cur is select 'x' from FIN_CLIENTE
        where CLI_CODIGO = :BDOC.DOC_CLI;
    primary_dummy  VARCHAR2(1);
begin
    if ( ( :BDOC.DOC_CLI is not null ) ) then
        open primary_cur;
        fetch primary_cur into primary_dummy;
        if ( not primary_cur%found ) then
           message('Cliente inexistente!');
           close primary_cur;
           raise form_trigger_failure;
        end if;
        close primary_cur;
    end if;
end;

if :bcuo.s_marca is not null and :bcuo.s_marca = 'X' and :bcuo.cuo_nro_doc is null then
   if :system.cursor_record = '1' then
      pl_mm('No existen cuotas para seleccionar.');
   else   
   	  pl_mm('Ya no existen cuotas para seleccionar.');
   end if;   
   raise form_trigger_failure;
end if;

if :bcuo.s_marca is not null then                                   
     if :bcuo.s_marca not in ('.', '..') then
        :bcuo.s_marca := upper('x');
        if nvl(:bdoc.doc_neto_Exen_mon,0) <> 0 then
          if :bcuo.s_dife < 0 then
        	  pl_me('El importe de la distribucion de pagos es mayor al importe del recibo');
          end if;	 
          if :bcuo.s_imp_pago is null then
            if :bcuo.cuo_saldo_mon <= :bcuo.s_dife then
              :bcuo.s_imp_pago := :bcuo.cuo_saldo_mon;
            else
        	    :bcuo.s_imp_pago := :bcuo.s_dife;  
            end if;	  
           end if;  
        else
         if :bcuo.s_imp_pago is null then
         	:bcuo.s_imp_pago := :bcuo.cuo_saldo_mon;
         end if;	
        end if;        
        if :bcuo.doc_fec_doc > :bdoc.doc_fec_doc then
          pl_me('La fecha de pago debe ser mayor o igual a la factura a pagar');
        end if;
     end if;

    IF :BCUO.S_MARCA = 'X' THEN      
      	:PARAMETER.P_SELECCION := REPLACE(:PARAMETER.P_SELECCION, :BCUO.CUO_CLAVE_DOC||TO_CHAR(:BCUO.CUO_FEC_VTO,'DDMMYYYY')||',',NULL);
       	:PARAMETER.P_SELECCION := :PARAMETER.P_SELECCION||:BCUO.CUO_CLAVE_DOC||TO_CHAR(:BCUO.CUO_FEC_VTO,'DDMMYYYY')||',';
       	if :bcuo.cuo_nro_doc > 0 then
       	   :bcuo.s_contador  := 1 ;
       	end if;
    END IF;	
ELSE
    :PARAMETER.P_SELECCION := REPLACE(:PARAMETER.P_SELECCION, :BCUO.CUO_CLAVE_DOC||TO_CHAR(:BCUO.CUO_FEC_VTO,'DDMMYYYY')||',', NULL); 	 
    :bcuo.s_contador  := 0 ;
end if;

IF :bdoc.s_cuenta = :PARAMETER.EMPR_CLI_CODIGO THEN -- Cliente Record Electric
   :PARAMETER.P_SELECCION := NULL;
END IF;

if :system.cursor_value is not null then
   pl_validar_entrada;          
end if;
if :system.cursor_record = '1' then
   go_item('bdoc.doc_neto_Exen_mon');
else
   previous_record;      
end if;

pl_validar_entrada;                 
if :bcuo.s_marca is not null then

  if :bcuo.s_marca = '.' then
   :bcuo.s_marca    := null;
   :bcuo.s_imp_pago := null;   
   --go_block('bpie');
   go_block('bmp');
  elsif    
   :bcuo.s_marca = '..' then    
   :bcuo.s_marca    := null;
   :bcuo.s_imp_pago := null;
   --go_block('bpie'); 
   go_block('bmp');
   :bdoc.doc_neto_exen_mon := :bcuo.sum_s_imp_pago;    

    if :bdoc.s_tasa_ofic is null then
      :bdoc.s_tasa_ofic := nvl(:bdoc.doc_neto_exen_loc,0) / nvl(:bdoc.doc_neto_exen_mon,0);
    end if;	
    :BDOC.DOC_NETO_EXEN_LOC :=    ROUND(NVL(:BDOC.DOC_NETO_EXEN_MON,0)  * NVL(:BDOC.S_TASA_OFIC,1), :PARAMETER.P_CANT_DECIMALES_LOC);
  else     
   pp_sumar_intereses_marcados;  	
   next_item;

   if ( :bcuo.s_imp_interes = 0 or :bcuo.s_imp_interes is null )then
     next_item;          
   end if;

  end if;
else
  :bcuo.s_imp_pago := null;
  if :system.last_record = upper('true') then   
    --go_block('bpie');
    go_block('bmp');
  else
    next_record;
  end if;
end if;

IF :SYSTEM.LAST_RECORD='FALSE' THEN 
	  NEXT_RECORD;
ELSE
	 NULL;
END IF;	  

IF :BCUO.DOC_FEC_DOC IS NULL THEN 
	 DELETE_RECORD;
END IF;

IF :BDOC.S_CLI_EXENTO_INTERES = 'S' THEN
   PL_ME('Este cliente está exento de pagar interés moratorio.');
END IF;

IF :BCUO.S_IMP_INTERES = 0 THEN
    NEXT_ITEM; --PL_ME('Esta cuota no tiene interés moratorio');
END IF;

IF :BCUO.S_IMP_INTERES > 0 THEN		
DECLARE
	X_POS NUMBER(8);
	Y_POS NUMBER(8);	
BEGIN
		IF NVL(:BCUO.S_MARCA,' ') = 'X' THEN			
		   PP_OBTENER_POSICION_ITEM('WINDOW0', X_POS, Y_POS );		   
		   PP_GLOBAL.BLOQUE_REFRESH := 'BCUO';
		   PP_ABRIR_FORM('FACI029','INGRESO DE VENTA DE INTERES', (X_POS-210), (Y_POS-190) );
		END IF;
END;
