END IF;

if nvl(:bcuo.s_imp_pago,0)  < 0 then
	 pl_me('El importe de pago debe ser mayor a cero');
end if;


if nvl(:bcuo.s_imp_pago, 0) > 0  and nvl(:bcuo.s_marca, '.') <> upper('x') then
  :bcuo.s_imp_pago := null;
end if;	

if nvl(:bcuo.s_imp_pago,0) > nvl(:bcuo.cuo_saldo_mon,0) then
	pl_me('El importe de pago no puede sobrepasar el saldo de la cuota.........!.');
end if;

if :bmp.mp_medio_pago = '.' then
   clear_record;
   go_block('bpie');
else
	next_item;
end if;

IF :BMP.MP_IMPORTE < 0 THEN	  
	  PL_EXHIBIR_ERROR('El importe de pago no puede ser negativo.');
END IF;	  

IF :BMP.MP_IMPORTE = 0 THEN	  
	  PL_EXHIBIR_ERROR('El importe de pago no puede ser 0 (cero).');
END IF;	  

IF :BMP.MP_MEDIO_PAGO IS NOT NULL AND :BMP.MP_IMPORTE IS NULL THEN	  
	 PL_EXHIBIR_ERROR('El importe de pago no puede quedar vacío.');
END IF;

  if :bmp.mp_medio_pago in (1,9) then --> Efectivo y retención

			:bmp.mp_nro_referencia    := null;
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;           
      next_record ;

  else
  	next_item;
  end if;

  if :bmp.mp_medio_pago in ( 1, 9) then --> Efectivo y Retencion

			:bmp.mp_nro_referencia   := null;
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;
			:bmp.mp_clave_transferencia := null;        
      next_record ;

  elsif :bmp.mp_medio_pago = 2 then   --> Tarjeta de Débito

			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;
			:bmp.mp_clave_transferencia := null;              
      next_record ;

  elsif :bmp.mp_medio_pago = 3 then   --> Tarjeta de Crédito

			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;
			:bmp.mp_clave_transferencia := null;			
      next_record ;      

  elsif :bmp.mp_medio_pago = 7 then   --> Transferencia Bancaria

  		pp_validar_transferencia;

			:bmp.mp_cheque_nro       := null;			
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;              
      next_item ; 


  else
  	next_item;
  end if;

DECLARE

TEXTO VARCHAR2(10)  ;
vDATE DATE;

BEGIN  

if :bmp.mp_medio_pago in (4,5) and :bmp.mp_fecha_cheque is null then --> Cheque Día / Diferido / Transfe
    pl_mm('Para medio de pago '||:bmp.fp_descripcion||' debe ingresar fecha de la operación.');
    raise form_trigger_failure;
end if;   

IF :BMP.MP_FECHA_CHEQUE IS NOT NULL THEN

     TEXTO := REPLACE(NAME_IN('BMP.MP_FECHA_CHEQUE'), '/','');
     TEXTO := REPLACE(TEXTO, '-' , '');
     TEXTO := SUBSTR(TEXTO,1,2);

     IF TO_NUMBER(TEXTO) > 31 THEN       
       PL_EXHIBIR_ERROR('Atención : FECHA INVÁLIDA.');       
     END IF; 

               vDATE    :=  FP_DEVUELVE_FECHA(:BMP.MP_FECHA_CHEQUE) ;  
   :BMP.MP_FECHA_CHEQUE := TO_CHAR( vDATE , 'DD-MM-YYYY') ;  

END IF;




END;

  if :bmp.mp_medio_pago in ( 1, 9) then --> Efectivo y Retencion

			:bmp.mp_nro_referencia   := null;
			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;           
      next_record ;

  elsif :bmp.mp_medio_pago = 2 then   --> Tarjeta de Débito

			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;              
      next_record ;

  elsif :bmp.mp_medio_pago = 3 then   --> Tarjeta de Crédito

			:bmp.mp_cheque_nro       := null;
			:bmp.mp_fecha_cheque     := null;
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;              
      next_record ;      

  elsif :bmp.mp_medio_pago = 7 then   --> Transferencia Bancaria

			:bmp.mp_cheque_nro       := null;			
			:bmp.mp_fecha_cheque_vto := null;
			:bmp.mp_librador_cheque  := null;              
      next_record ; 


  else
  	next_item;
  end if;

if :bmp.mp_medio_pago in (4,5) and :bmp.mp_cheque_nro is null then --> Cheque Día / Diferido
    pl_mm('Para medio de pago '||:bmp.fp_descripcion||' debe ingresar el número de cheque.');
    raise form_trigger_failure;
end if;

DECLARE

TEXTO VARCHAR2(10)  ;
vDATE DATE;

BEGIN  

IF :BMP.MP_FECHA_CHEQUE_VTO IS NOT NULL THEN

     TEXTO := REPLACE(NAME_IN('BMP.MP_FECHA_CHEQUE_VTO'), '/','');
     TEXTO := REPLACE(TEXTO, '-' , '');
     TEXTO := SUBSTR(TEXTO,1,2);

     IF TO_NUMBER(TEXTO) > 31 THEN       
       PL_EXHIBIR_ERROR('Atención : FECHA INVÁLIDA.');       
     END IF; 

                   vDATE    :=  FP_DEVUELVE_FECHA(:BMP.MP_FECHA_CHEQUE_VTO) ;  
   :BMP.MP_FECHA_CHEQUE_VTO := TO_CHAR( vDATE , 'DD-MM-YYYY') ;  

END IF;


END;

BEGIN
  IF :SYSTEM.MODE <> 'NORMAL' THEN
     EXIT_FORM;
  ELSE
    CLEAR_FORM(NO_VALIDATE, FULL_ROLLBACK);
    EXIT_FORM;
  END IF;
END;


BEGIN	

	-- El valor estático 972 es el resultado de la diferencia entre ( :PARAMETER.P_SELECCION - 28 )


	IF :BPIE.SELEC_TODOS = 'X' THEN		
		GO_BLOCK('BCUO');
		FIRST_RECORD ;		
		LOOP		

		if :bcuo.doc_fec_doc <= :bdoc.doc_fec_doc then
		   :BCUO.S_MARCA := 'X' ;		SYNCHRONIZE;		
		end if;

		if :bcuo.s_marca = 'X' and :bcuo.cuo_nro_doc > 0 then
			 :bcuo.s_contador := 1; else :bcuo.s_contador := 0; 
		end if;

		IF :SYSTEM.LAST_RECORD='TRUE' OR LENGTH(:PARAMETER.P_SELECCION) > 972 or :bcuo.sum_contador_seleccion >= 24 or :bcuo.s_marca is null THEN			  			
				if :bcuo.doc_fec_doc <= :bdoc.doc_fec_doc then			  
					  GO_ITEM('BCUO.S_MARCA');
					 :BCUO.S_MARCA := 'X' ;				  
					  DO_KEY('NEXT_ITEM');		  
					  GO_ITEM('BCUO.S_IMP_PAGO');
				end if;	  
		    EXIT ;
		 END IF;				
     NEXT_RECORD ;

		END LOOP;			
	END IF;	


	IF :BPIE.SELEC_TODOS = 'N' THEN		
		GO_BLOCK('BCUO');
		LAST_RECORD ;		
		LOOP

	  :bcuo.s_contador  := 0	  ;
	  :BCUO.S_IMP_PAGO  := NULL ;
		:BCUO.S_MARCA     := NULL ; SYNCHRONIZE;
		 PREVIOUS_RECORD ;

		IF :SYSTEM.CURSOR_RECORD = '1' THEN
			   :bcuo.s_contador  := 0	   ;
			 	 :BCUO.S_IMP_PAGO  := NULL ;
		     :BCUO.S_MARCA     := NULL ; SYNCHRONIZE; 			  
			  GO_ITEM('BCUO.S_MARCA');			 		    
		    EXIT ;
		END IF;		


		END LOOP;			

	END IF;		



END;

if  :bdoc.form_pago = 2 then -- cheque adelantado..    
	if nvl(:bcheq.cheq_bco, '.') = '.' then
		delete_record;  
		go_block('bpie_cheq');                                     
	else   
	  next_item;                           
	end if;	
end if;

if  :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
	if :bcheq.cheq_serie is null then
		pl_me('Debe ingresar la Serie del cheque');
	end if;
end if;

if  :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
	if :bcheq.cheq_nro is null then
		pl_me('Debe ingresar El Nro del cheque');
	--else
		--pp_validar_nro_cheq(:bcheq.cheq_bco, :bcheq.cheq_serie, :bcheq.cheq_nro);
	end if;
end if;

if :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
	--:bcheq.cheq_mon := :bdoc.doc_mon;


	if :bcheq.cheq_mon is not null then

		  if :bcheq.cheq_mon not in (1,2) then  --Gs o Us
		  	pl_me('La moneda del cheque debe ser en Gs o US');
		  end if;
		  pp_traer_desc_mone(:bcheq.cheq_mon, :bcheq.mon_Desc, :bcheq.mon_simbolo, :bcheq.cant_Deci);


		  	  PL_FORMAT_MASK('Bcheq.cheq_importe'              , :bcheq.cant_deci);	   
	        PL_FORMAT_MASK('Bcheq.sum_cheq_importe'          , :bcheq.cant_deci);
				  PL_FORMAT_MASK('Bcheq.sum_cheq_importe_mon_fact' , :BDOC.W_MON_DEC_IMP );
				  PL_FORMAT_MASK('Bcheq.cheq_importe_mon_fact'     , :BDOC.W_MON_DEC_IMP );   


		  if :bdoc.doc_mon = 1 and :bcheq.cheq_mon = 1   then --recibo Gs. cheq Gs
		  	 :bcheq.cheq_tasa := 1;		  	 
		  elsif 	:bdoc.doc_mon = 1 and :bcheq.cheq_mon = 2 then --recibo Gs. cheq Us  
		  	 :bcheq.cheq_tasa := :bdoc.w_doc_tasa_us;
		  elsif :bdoc.doc_mon = 2 and :bcheq.cheq_mon = 1   then --recibo Us. cheq Gs  	 
		  	 :bcheq.cheq_tasa := :bdoc.s_Tasa_ofic;
		  elsif :bdoc.doc_mon = 2 and :bcheq.cheq_mon = 2  then --recibo Us. cheq Us  	 
		    :bcheq.cheq_tasa := :bdoc.s_tasa_ofic;
		  else
		     pl_me('Error al seleccionar la monde dal cheque!!!!!');
		  end if;	





	else
		pl_me('Debe ingresar el codigo de la moneda del cheque');
	end if;
end if;

if  :bdoc.form_pago = 2 then --si es contado y cheque adelantado..

	 if :bcheq.s_cheq_fec_emis is null then
		 	   pl_me('Debe ingresar la fecha de emisón del cheque');
	 end if;	
	 AF_VALIDAR_FECHA ('OVF', :SYSTEM.CURSOR_FIELD, NULL, :GLOBAL.FECHA_SISTEMA); 
	 :Bcheq.cheq_fec_emis := TO_DATE(:Bcheq.s_cheq_fec_emis,'DD/MM/YYYY');

	/*			
	 if :bcheq.cheq_fec_emis > (:bdoc.doc_fec_doc + fp_devu_max_dias_cheq(:bdoc.doc_cli, :bcheq.cheq_mon))	then	
	  	pl_me('La fecha de emision del cheque no puede ser Mayor a '||to_char((:bdoc.doc_fec_doc + + fp_devu_max_dias_cheq(:bdoc.doc_cli, :bcheq.cheq_mon)), 'dd-mm-yyyy'));
	 end if;	
	 */
end if;

if  :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
	if :bcheq.s_cheq_fec_depositar is null then
	 pl_me('Debe ingresar la fecha a depositar del cheque');
	end if;	
	AF_VALIDAR_FECHA ('OVF', :SYSTEM.CURSOR_FIELD, NULL, :GLOBAL.FECHA_SISTEMA); 
	:Bcheq.cheq_fec_depositar := TO_DATE(:Bcheq.s_cheq_fec_depositar,'DD/MM/YYYY');	

	if :bcheq.cheq_fec_depositar < :bcheq.cheq_fec_emis then
		 pl_me('La fecha de emision del cheuqe no puede ser superior a la fecha a depositar');
	end if;	
end if;	

	/*
  if :bcheq.cheq_fec_depositar > (:bdoc.doc_fec_doc + fp_devu_max_dias_cheq(:bdoc.doc_cli, :bcheq.cheq_mon))	then
		 pl_me('La fecha a depositar del cheque no puede ser Mayor a '||to_char((:bdoc.doc_fec_doc  + fp_devu_max_dias_cheq(:bdoc.doc_cli, :bcheq.cheq_mon)), 'dd-mm-yyyy'));
	end if;	
	*/

if :bdoc.form_pago = 2 then --si es contado y cheque adelantado..  
	if nvl(:bcheq.cheq_importe,0) <= 0 then
		pl_me('Debe ingresar el importe del cheque');
	end if;
	if :bcheq.cheq_mon = 1 then --si es en guaranies
	 :bcheq.cheq_importe_loc :=  :bcheq.cheq_importe;
	else --si es en dolars
	 :bcheq.cheq_importe_loc := round((:bcheq.cheq_importe_loc*:bdoc.s_tasa_ofic),0);	 
	end if; 	

	if :bcheq.cheq_mon = :bdoc.doc_mon then --si las monedas del cheque y el recibo son iguales.....
		 :bcheq.cheq_importe_mon_fact := :bcheq.cheq_importe;
	else --si las monedas del cheque y el recibo son distintas.....................
		if :bcheq.cheq_mon = 1 then --si la moneda del chequ es en Gs y la moneda de la factura en Us
		  :bcheq.cheq_importe_mon_fact := round((:bcheq.cheq_importe /:bdoc.s_tasa_ofic), :BDOC.W_MON_DEC_IMP );
		elsif :bcheq.cheq_mon = 2 then --si la moneda del cheque es en Us y la moneda de la factura en Gs
		  :bcheq.cheq_importe_mon_fact := round((:bcheq.cheq_importe *:bcheq.cheq_tasa),0);		
		end if;

	end if;	

end if;

if :bdoc.form_pago = 2 then --si es contado y cheque adelantado..  
 if :bcheq.cheq_mon = 1 then --si es en Gs
 	  :bcheq.cheq_tasa := 1;
 end if;


end if;

if :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
  :bcheq.cheq_titular := :bcheq.cheq_titular;
end if;

if :bdoc.form_pago = 2 then --si es contado y cheque adelantado..		if :bcheq.cheq_titular is null then
	 if :bcheq.cheq_titular is null then
		  :bcheq.cheq_titular := :bdoc.s_doc_cli_nom;
	 end if;	  
end if;

if  :bdoc.form_pago = 2 then --si es contado y cheque adelantado..
	if :bcheq.cheq_orden is null then
		 :bcheq.cheq_orden := 'RECORD ELECTRIC S.A.E.C.A.';
	END IF;
end if;

if :bdoc.form_pago= 2 then --si el tipo de factura es contado
	 	if :bcheq.cheq_nro_cta_cheq is null then
			 pl_me('Debe ingresar el Nro de cuenta del cheque');
		end if;
end if;
